INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (124,'01KWJDMEE373K2CH5AXAJ7B6MN',12,'Bachelor of Business Administration (BBA)','bachelors',36,'English','Toolkit source: non_exclusive / Malta / row 159.','ELIGIBILITY:\nTBA\n\nREQUIREMENTS / DOCUMENTS:\nEducation: IAU requires either evidence of an earned high school diploma, General Educational Development (GED) test, or the successful completion of 12 semester units earned at an appropriately accredited postsecondary institution or foreign equivalent. Exceptions may be made on a case-by-case basis.\nProfessional Experience: IAU recommends 1 year of full-time professional experience, in any organization, including, but not limited to, private, public, for-profit, non-profit, start-ups, or established corporate organizations.\nInformation Technology: IAU requires students to possess computer and internet skills sufficient to effectively participate in IAU\'s pedagogical model and conduct research at the undergraduate level.\nInternational American University (USA)\n\nTBA\n\nEducation: IAU requires either evidence of an earned high school diploma, General Educational Development (GED) test, or the successful completion of 12 semester units earned at an appropriately accredited postsecondary institution or foreign equivalent. Exceptions may be made on a case-by-case basis. Professional Experience: IAU recommends 1 year of full-time professional experience, in any organization, including, but not limited to, private, public, for-profit, non-profit, start-ups, or established corporate organizations. Information Technology: IAU requires students to possess computer and internet skills sufficient to effectively participate in IAU’s pedagogical model and conduct research at the undergraduate level.','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (125,'01KWJDMEE4PWSFMWQ88BREPQCS',12,'Master of Business Administration (MBA)','masters',24,'English','Toolkit source: non_exclusive / Malta / row 160.','ELIGIBILITY:\nTBA\n\nREQUIREMENTS / DOCUMENTS:\nEducation: IAU requires evidence of an earned bachelor degree in a related major or discipline. Other disciplines may be acceptable and shall be reviewed on a case-by-case basis, and they may require prerequisite courses. All degrees must be earned at an appropriately accredited institution or foreign equivalent. IAU understands the differing rigor of institutions and grading scales around the world, and IAU evaluates prior academic credentials within their own context. Exceptions shall be reviewed on a case-by-case basis.\nProfessional Experience: IAU recommends 3 years of full-time professional experience, including, but not limited to, private, public, for-profit, non-profit, start-ups, or established corporate organizations.\nInformation Technology: IAU requires students to possess computer and internet skills sufficient to effectively participate in IAU\'s pedagogical model and conduct research at the graduate level.\nInternational American University (USA)\n\nTBA\n\nEducation: IAU requires evidence of an earned bachelor degree in a related major or discipline. Other disciplines may be acceptable and shall be reviewed on a case-by-case basis, and they may require prerequisite courses. All degrees must be earned at an appropriately accredited institution or foreign equivalent. IAU understands the differing rigor of institutions and grading scales around the world, and IAU evaluates prior academic credentials within their own context. Exceptions shall be reviewed on a case-by-case basis. Professional Experience: IAU recommends 3 years of full-time professional experience, including, but not limited to, private, public, for-profit, non-profit, start-ups, or established corporate organizations. Information Technology: IAU requires students to possess computer and internet skills sufficient to effectively participate in IAU’s pedagogical model and conduct research at the graduate level.','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:37',NULL);
