INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (953,'01KWJDMEXE0192ZSS39WZ6WYYW',56,'KEDGE Bachelors','bachelors',36,'English','Language requirement: TOEIC 650 or TOEFL IBT 62 or IELTS 5.5 (only for taking admission in 3rd year) but if taking admission in 1st and 2nd year no need of english proficiency\n\nToolkit source: non_exclusive / France Spain / row 157.','REQUIREMENTS / DOCUMENTS:\nAge limit: upto 27 years, Requirement for taking admission in 1st year:a secondary school diploma (such as a french baccalauréat or a foreign qualification of an equivalent level) and for 2nd year: a higher education pathway of 1 year* (Bac+1), completed in the field of economics, management, and business, with the presentation of 60 ECTS credits validated.\nRequirement for 3trd year: a French diploma Bac+2 (BTS or DUT) or foreign qualification of an equivalent level in the field of economics, management, and business\na higher education pathway of 2 years*, completed in the field of economics, management, and business, with the presentation of 120 ECTS credits validated;\n\nAge limit: upto 27 years, Requirement for taking admission in 1st year:a secondary school diploma (such as a french baccalauréat or a foreign qualification of an equivalent level) and for 2nd year: a higher education pathway of 1 year* (Bac+1), completed in the field of economics, management, and business, with the presentation of 60 ECTS credits validated. Requirement for 3trd year: a French diploma Bac+2 (BTS or DUT) or foreign qualification of an equivalent level in the field of economics, management, and business a higher education pathway of 2 years*, completed in the field of economics, management, and business, with the presentation of 120 ECTS credits validated;\n\nTOEIC 650 or TOEFL IBT 62 or IELTS 5.5 (only for taking admission in 3rd year) but if taking admission in 1st and 2nd year no need of english proficiency','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:34',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (954,'01KWJDMEXE0192ZSS39WZ6WYYY',56,'International BBA','bachelors',48,'English','Language requirement: IELTS 5.5 required and 6.5 for taking admission in 3rd year\n\nToolkit source: non_exclusive / France Spain / row 158.','REQUIREMENTS / DOCUMENTS:\nAdmission to First year: •    Academic transcripts of the last 2 years of high school\n•    A copy of your high school diploma (if you\'ve already graduated)\n•    A copy of your passport or ID Card\n•    A CV\n•    A 5.5 IELTS level\n\nAdmission to First year: • Academic transcripts of the last 2 years of high school • A copy of your high school diploma (if you’ve already graduated) • A copy of your passport or ID Card • A CV • A 5.5 IELTS level\n\nIELTS 5.5 required and 6.5 for taking admission in 3rd year','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:34',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (955,'01KWJDMEXFEDWS0Q0GV20JKXMP',56,'Masters in Management','masters',24,'English','Language requirement: A current CV.\nA copy of your passport or ID.\nOne letter of recommendation.\nEnglish language proficiency certificate: TOEFL > 550 / TOEIC > 785 / IBT > 80 / IELTS > 6 / Duolingo (105) / PTE (46)\n\nToolkit source: non_exclusive / France Spain / row 159.','REQUIREMENTS / DOCUMENTS:\nAn international bachelor\'s degree, with at least 2 years of higher education undertaken outside of France and documents required are CV, LOR and SOP\n\nAn international bachelor\'s degree, with at least 2 years of higher education undertaken outside of France and documents required are CV, LOR and SOP\n\nA current CV. A copy of your passport or ID. One letter of recommendation. English language proficiency certificate: TOEFL > 550 / TOEIC > 785 / IBT > 80 / IELTS > 6 / Duolingo (105) / PTE (46)','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:34',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (956,'01KWJDMEXFEDWS0Q0GV20JKXMR',56,'MSc in International Purchasing & Innovation Management','masters',24,'English','Language requirement: English proficiency is required and Scholarship available\n\nToolkit source: non_exclusive / France Spain / row 160.','REQUIREMENTS / DOCUMENTS:\nShort Track (4 years + of higher education):\n- Level of studies: A university-level Master\'s Year 1 (M1) successfully completed, or an International Bachelor\'s degree (4 years of higher education), or 240 ECTS credits attesting to a validated university-level M1 qualification.\n- English level: TOEIC (785)/ TOEFL IBT (79)/ IELTS (6)/ Cambridge First (160/B2)/ Cambridge Advanced (180/B2)/ Duolingo (105)/ PTE (50)/ Linguaskill (169) - exemption for native English speakers or candidates who have had more than one year\'s work experience in an English-speaking country. And for Long Track (3 years + of higher education):\n- Level of studies: A university Bachelor\'s degree (three years of higher education), or an equivalent programme of 3 years of university study validated at Level L3, corresponding to 180 ECTS credits (or equivalent).\n- Level of English: TOEIC (720)/ IELTS (5.5)/ TOEFL IBT (70)/ Cambridge Preliminary (153)/ Duolingo (100)/ PTE (41)/ Linguaskill (153) - exemption for native english speakers or candidates who have had more than one year\'s work experience in an English-speaking country\n\nShort Track (4 years + of higher education): - Level of studies: A university-level Master’s Year 1 (M1) successfully completed, or an International Bachelor’s degree (4 years of higher education), or 240 ECTS credits attesting to a validated university-level M1 qualification. - English level: TOEIC (785)/ TOEFL IBT (79)/ IELTS (6)/ Cambridge First (160/B2)/ Cambridge Advanced (180/B2)/ Duolingo (105)/ PTE (50)/ Linguaskill (169) - exemption for native English speakers or candidates who have had more than one year\'s work experience in an English-speaking country. And for Long Track (3 years + of higher education): - Level of studies: A university Bachelor’s degree (three years of higher education), or an equivalent programme of 3 years of university study validated at Level L3, corresponding to 180 ECTS credits (or equivalent). - Level of English: TOEIC (720)/ IELTS (5.5)/ TOEFL IBT (70)/ Cambridge Preliminary (153)/ Duolingo (100)/ PTE (41)/ Linguaskill (153) - exemption for native english speakers or candidates who have had more than one year\'s work experience in an English-speaking country\n\nEnglish proficiency is required and Scholarship available','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:34',NULL);
