INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1054,'01KWJDMEZM4ZCA2H4VQD7HJPQY',66,'Bachelor of Tech for Management','bachelors',36,'English','Language requirement: Minimum required level for applicants for a program in English: IELTS 5.5 - TOEFL 70\n\nToolkit source: non_exclusive / France Spain / row 272.','REQUIREMENTS / DOCUMENTS:\nThe required documents are as follows:\nThe application form.\nA photocopy of a valid ID (front and back).\nCopies of diplomas earned and transcripts from the past three years (including the baccalaureate transcript, if applicable). Documents must be certified true copies and translated into English or French if they are not in one of these two languages.\nA current school enrollment certificate for the 2024/2025 academic year, if available.\nA CV and a cover letter.\nResults from an official French language test (DELF, DALF, TCF) at a minimum B2 level for applicants whose native language is not French.\nResults from an official English language test (IELTS, TOEFL). If you cannot provide an official score, you will receive a link to take an online test.\nA letter of recommendation from a teacher, school principal, or employer (optional).\n€80 for the application fee\n\nThe required documents are as follows: The application form. A photocopy of a valid ID (front and back). Copies of diplomas earned and transcripts from the past three years (including the baccalaureate transcript, if applicable). Documents must be certified true copies and translated into English or French if they are not in one of these two languages. A current school enrollment certificate for the 2024/2025 academic year, if available. A CV and a cover letter. Results from an official French language test (DELF, DALF, TCF) at a minimum B2 level for applicants whose native language is not French. Results from an official English language test (IELTS, TOEFL). If you cannot provide an official score, you will receive a link to take an online test. A letter of recommendation from a teacher, school principal, or employer (optional). €80 for the application fee\n\nMinimum required level for applicants for a program in English: IELTS 5.5 - TOEFL 70','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1055,'01KWJDMEZM4ZCA2H4VQD7HJPR1',66,'MSc - Arts & Cultural Management','masters',24,'English','Language requirement: Minimum required English level: IELTS 6 - TOEFL 80\n\nToolkit source: non_exclusive / France Spain / row 273.','REQUIREMENTS / DOCUMENTS:\nCompleted application file \nID photo \nPhotocopy of official ID (both sides) \nPhotocopies of diplomas and reports obtained from baccalaureate level onwards (certified and translated into French for documents in neither French nor English) \nA tuition certificate for the year in progress if available \nCV + covering letter \nLetter of recommendation from a professor, head of institution or employer (optional) \n100 euros administrative fee + Individual Interview\n\nCompleted application file ID photo Photocopy of official ID (both sides) Photocopies of diplomas and reports obtained from baccalaureate level onwards (certified and translated into French for documents in neither French nor English) A tuition certificate for the year in progress if available CV + covering letter Letter of recommendation from a professor, head of institution or employer (optional) 100 euros administrative fee + Individual Interview\n\nMinimum required English level: IELTS 6 - TOEFL 80','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
