INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1080,'01KWJDMF01QXJFDXC6R5TSMC8A',66,'MBA - Master of Business Administration','masters',12,'English','Language requirement: Minimum required level in English: IELTS 6 - TOEFL 80\n\nToolkit source: non_exclusive / France Spain / row 299.','REQUIREMENTS / DOCUMENTS:\n4-year Bachelor or Master degree + minimum 3 years of work experience OR 3-year bachelor + minimum 5 years of work experience // Completed application file \nID photo \nPhotocopy of official ID (both sides) \nPhotocopies of diplomas and reports obtained from baccalaureate level onwards (certified and translated into French for documents in neither French nor English) \nA tuition certificate for the year in progress if available \nCV + covering letter \nLetter of recommendation from a professor, head of institution or employer (optional) \n100 euros administrative fee (reduced to 50 euros for scholarship students, subject to producing the definitive scholarship certificate for the academic year in progress\n3.0\n\n4-year Bachelor or Master degree + minimum 3 years of work experience OR 3-year bachelor + minimum 5 years of work experience // Completed application file ID photo Photocopy of official ID (both sides) Photocopies of diplomas and reports obtained from baccalaureate level onwards (certified and translated into French for documents in neither French nor English) A tuition certificate for the year in progress if available CV + covering letter Letter of recommendation from a professor, head of institution or employer (optional) 100 euros administrative fee (reduced to 50 euros for scholarship students, subject to producing the definitive scholarship certificate for the academic year in progress\n\nMinimum required level in English: IELTS 6 - TOEFL 80','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1081,'01KWJDMF02H6K0VPWQEN1VEGWZ',67,'Bachelor of International Business Administration','bachelors',36,'English','Language requirement: 700 TOEIC, 85 MBS English test by Méréos, 75 TOEFL, 5,5 IELTS, 90 Duolingo English Test, 60 ICIMS, Cambridge B2.\n\nToolkit source: non_exclusive / France Spain / row 303.','REQUIREMENTS / DOCUMENTS:\nCurriculum Vitae (in French or English according to the chosen track)\nCopy of the highest degree, in the original language. For documents that are not written in French, English or Spanish, please provide a certified translation into English or French.\nCopy of the official transcripts of the last 3 years of studies, including the current year, in the original language. For documents that are not written in French, English or Spanish, please provide a certified translation into English or French.\nIdentity card or passport\nOne identity photo + Application fees: 90 Euros + Individual Interview\nBachlelor - RNCP 6\n\nCurriculum Vitae (in French or English according to the chosen track) Copy of the highest degree, in the original language. For documents that are not written in French, English or Spanish, please provide a certified translation into English or French. Copy of the official transcripts of the last 3 years of studies, including the current year, in the original language. For documents that are not written in French, English or Spanish, please provide a certified translation into English or French. Identity card or passport One identity photo + Application fees: 90 Euros + Individual Interview\n\n700 TOEIC, 85 MBS English test by Méréos, 75 TOEFL, 5,5 IELTS, 90 Duolingo English Test, 60 ICIMS, Cambridge B2.','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1082,'01KWJDMF034K9Q2RSS32AH6PGR',67,'Master in Management - Grande Ecole Programme (Master)','masters',24,'English','Language requirement: 75 TOEFL IBT / 5.5 IELTS / 90 Duolingo / 60 ICIMS / Cambridge B2.\n\nToolkit source: non_exclusive / France Spain / row 304.','REQUIREMENTS / DOCUMENTS:\ncandidates having completed at least three progressive academic years after high school and obtained 180 ECTS credits (or credits deemed equivalent by the MBS Equivalence Commission).+ Pre-recorded Video Interview and Application fee: €90. Copy of your highest diploma (original language). Copy of official transcripts for the last 3 years of studies including the current year (original language). For documents not in French, English or Spanish: provide a certified translation into English or French. Curriculum Vitae (in French or English, according to the chosen track) · One ID photo · Identity card or passport.\nMasters - RNCP 7\n\ncandidates having completed at least three progressive academic years after high school and obtained 180 ECTS credits (or credits deemed equivalent by the MBS Equivalence Commission).+ Pre-recorded Video Interview and Application fee: €90. Copy of your highest diploma (original language). Copy of official transcripts for the last 3 years of studies including the current year (original language). For documents not in French, English or Spanish: provide a certified translation into English or French. Curriculum Vitae (in French or English, according to the chosen track) · One ID photo · Identity card or passport.\n\n75 TOEFL IBT / 5.5 IELTS / 90 Duolingo / 60 ICIMS / Cambridge B2.','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1083,'01KWJDMF046HAV12A3TXTGG0AE',68,'Bachelor in International Management','bachelors',36,'English','Language requirement: IELTS 6.0\n\nToolkit source: non_exclusive / France Spain / row 307.','REQUIREMENTS / DOCUMENTS:\ntranscripts of grades obtained during the last two years\nofficial score on a language test (French/English, depending on the desired language of instruction)*\ncopy of Baccalaureate or equivalent grades (if already obtained)\nphotocopy of an identity document\ncover letter\nresume\nletter of recommendation (optional)\nStudents from outside the EU should plan for consular procedures.Competition entry fee  : €100\n\ntranscripts of grades obtained during the last two years official score on a language test (French/English, depending on the desired language of instruction)* copy of Baccalaureate or equivalent grades (if already obtained) photocopy of an identity document cover letter resume letter of recommendation (optional) Students from outside the EU should plan for consular procedures.Competition entry fee : €100\n\nIELTS 6.0','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1084,'01KWJDMF051GNCSV3P9QATJ9B0',68,'Grande École programme (Integrated)',NULL,60,'English','Language requirement: IELTS 6.0\n\nToolkit source: non_exclusive / France Spain / row 308.','REQUIREMENTS / DOCUMENTS:\ntranscripts of grades obtained during the last two years of secondary school\ncopy of baccalaureate results or equivalent (if obtained)\nresume\ncopy of an identity document\nofficial score on an English test and, where applicable, a French test (*)\nletter(s) of recommendation (optional)\nNon-EU students, consular procedures to be expected. Applications fees are 100 euros (Non-refundable)\n\ntranscripts of grades obtained during the last two years of secondary school copy of baccalaureate results or equivalent (if obtained) resume copy of an identity document official score on an English test and, where applicable, a French test (*) letter(s) of recommendation (optional) Non-EU students, consular procedures to be expected. Applications fees are 100 euros (Non-refundable)\n\nIELTS 6.0','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1085,'01KWJDMF051GNCSV3P9QATJ9B3',68,'MSc in EU-Asia Digital Marketing & Business','masters',18,'English','Language requirement: IELTS 6.5\n\nToolkit source: non_exclusive / France Spain / row 309.','REQUIREMENTS / DOCUMENTS:\na 4-year Bachelor Degree with no expected work experience (equivalent to 240 ECTS credits)\na 3-year Bachelor Degree with a minimum 3 years of relevant professional experience (equivalent to 180 ECTS credits). Candidates with less than 3 years of professional experience and still willing to study one of our MScs are invited to apply for the Double Degree Qualification : Master in Management + MScApplications fees are 100 euros and are non-refundable.                                                                                              The copy of an ID, A resume, A cover letter, All transcripts of higher education\nA copy of the Bachelor Degree or if you have not yet graduated, a school certificate for the current or 1st semester/quarter transcript (if available)\nA score in an official French and/or English language proficiency test (*)\nAny additional and optional document highlighting your application (recommendation letters, GMAT certificate, other certificates, awards, etc.)\n3.0\n\na 4-year Bachelor Degree with no expected work experience (equivalent to 240 ECTS credits) a 3-year Bachelor Degree with a minimum 3 years of relevant professional experience (equivalent to 180 ECTS credits). Candidates with less than 3 years of professional experience and still willing to study one of our MScs are invited to apply for the Double Degree Qualification : Master in Management + MScApplications fees are 100 euros and are non-refundable. The copy of an ID, A resume, A cover letter, All transcripts of higher education A copy of the Bachelor Degree or if you have not yet graduated, a school certificate for the current or 1st semester/quarter transcript (if available) A score in an official French and/or English language proficiency test (*) Any additional and optional document highlighting your application (recommendation letters, GMAT certificate, other certificates, awards, etc.)\n\nIELTS 6.5','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
