INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1088,'01KWJDMF078SADM5PA6453RTX7',68,'MSc in International Luxury Management','masters',18,'English','Language requirement: IELTS 6.5\n\nToolkit source: non_exclusive / France Spain / row 312.','REQUIREMENTS / DOCUMENTS:\nApplications fees are 100 euros and are non-refundable. The copy of an ID\nA resume\nA cover letter\nAll transcripts of higher education\nA copy of the Bachelor Degree or if you have not yet graduated, a school certificate for the current or 1st semester/quarter transcript (if available)\nA score in an official French and/or English language proficiency test (*)\nAny additional and optional document highlighting your application (recommendation letters, GMAT certificate, other certificates, awards, etc.) a 4-year Bachelor Degree with no expected work experience (equivalent to 240 ECTS credits)\na 3-year Bachelor Degree with a minimum 3 years of relevant professional experience (equivalent to 180 ECTS credits).\n\nApplications fees are 100 euros and are non-refundable. The copy of an ID A resume A cover letter All transcripts of higher education A copy of the Bachelor Degree or if you have not yet graduated, a school certificate for the current or 1st semester/quarter transcript (if available) A score in an official French and/or English language proficiency test (*) Any additional and optional document highlighting your application (recommendation letters, GMAT certificate, other certificates, awards, etc.) a 4-year Bachelor Degree with no expected work experience (equivalent to 240 ECTS credits) a 3-year Bachelor Degree with a minimum 3 years of relevant professional experience (equivalent to 180 ECTS credits).\n\nIELTS 6.5','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1089,'01KWJDMF082JCNHJMVY61E0CXC',68,'MSc in Business Analytics','masters',24,'English','Language requirement: IELTS 6.5\n\nToolkit source: non_exclusive / France Spain / row 313.','REQUIREMENTS / DOCUMENTS:\nThe MSc in Business Analytics can be completed in one year if you hold 240 ECTS credits or a 3-year bachelor degree with a minimum 3 years of relevant professional experience. In two years if you hold 180 ECTS credits. The evaluation committee conducts a preliminary academic assessment of the application file. This assessment may be eliminatory, resulting in a decision of non-admission if the application does not meet the required criteria or expectations. The copy of an ID\nA resume, A cover letter, All transcripts of higher education\nA copy of the Bachelor Degree or if you have not yet graduated, a school certificate for the current or 1st semester/quarter transcript (if available), A score in an official French and/or English language proficiency test (*), Any additional and optional document highlighting your application (recommendation letters, GMAT certificate, other certificates, awards, etc.), (*) English and/or French language proficiency tests are mandatory, depending on the applicant\'s chosen language of study. However, applicants are exempt from providing an English and/or French score if they:\n- Have studied at least one year in French and/or English\n- Have French and/or English as their mother tongue\n\nThe MSc in Business Analytics can be completed in one year if you hold 240 ECTS credits or a 3-year bachelor degree with a minimum 3 years of relevant professional experience. In two years if you hold 180 ECTS credits. The evaluation committee conducts a preliminary academic assessment of the application file. This assessment may be eliminatory, resulting in a decision of non-admission if the application does not meet the required criteria or expectations. The copy of an ID A resume, A cover letter, All transcripts of higher education A copy of the Bachelor Degree or if you have not yet graduated, a school certificate for the current or 1st semester/quarter transcript (if available), A score in an official French and/or English language proficiency test (*), Any additional and optional document highlighting your application (recommendation letters, GMAT certificate, other certificates, awards, etc.), (*) English and/or French language proficiency tests are mandatory, depending on the applicant’s chosen language of study. However, applicants are exempt from providing an English and/or French score if they: – Have studied at least one year in French and/or English – Have French and/or English as their mother tongue\n\nIELTS 6.5','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1090,'01KWJDMF09RVC2YTB3DJ0XPE10',69,'Bachelor en Management','bachelors',36,'English','Language requirement: IELTS overall score 6.0\n\nToolkit source: non_exclusive / France Spain / row 316.','REQUIREMENTS / DOCUMENTS:\nApplication file (PDF file provided by the institution),\nProof of identity (preferably a passport)\nresume\nLetter of motivation (academic and professional project),\nTwo most recent transcripts (minimum)\nCopy of diplomas obtained,\nAny other document that could strengthen your application (language test, certification, letter of recommendation, etc.)\n1.0\n\nApplication file (PDF file provided by the institution), Proof of identity (preferably a passport) resume Letter of motivation (academic and professional project), Two most recent transcripts (minimum) Copy of diplomas obtained, Any other document that could strengthen your application (language test, certification, letter of recommendation, etc.)\n\nIELTS overall score 6.0','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
