INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1099,'01KWJDMF0G28CY1J9BY799TK7Q',70,'International BBA','bachelors',48,'English','Language requirement: TOEFL iBT: minimum score 80 \nIELTS Academic / IELTS Indicator: Indicator 6\n\nToolkit source: non_exclusive / France Spain / row 327.','REQUIREMENTS / DOCUMENTS:\nRegistration fees\n€  315  for the first year via the SESAME competition (scholarship recipients benefit from a 50% discount on registration fees)\n€ 98  for international admissions  in the 1st, 2nd and 3rd years                                                                                Students holding or in the process of obtaining an  international secondary education diploma  (e.g., High School Diploma, International Baccalaureate (IB), A-Levels, Abitur, GaoKao, Matura or equivalent).\n\nRegistration fees € 315 for the first year via the SESAME competition (scholarship recipients benefit from a 50% discount on registration fees) € 98 for international admissions in the 1st, 2nd and 3rd years Students holding or in the process of obtaining an international secondary education diploma (e.g., High School Diploma, International Baccalaureate (IB), A-Levels, Abitur, GaoKao, Matura or equivalent).\n\nTOEFL iBT: minimum score 80 IELTS Academic / IELTS Indicator: Indicator 6','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1100,'01KWJDMF0G28CY1J9BY799TK7S',70,'MSc Finance and Investment Banking','masters',24,'English','Language requirement: TOEFL iBT: 80. TOEFL \nIELTS Academic/IELTS Indicator: 6.0\n\nToolkit source: non_exclusive / France Spain / row 328.','REQUIREMENTS / DOCUMENTS:\nSpecific to the 2-year program\nOfficial copy of a Bachelor\'s degree equivalent to at least 180 ECTS or certificate of enrollment with an approximate date of graduation.                                                                                                                                    Specific to the 1-year program\nOfficial copy of an undergraduate degree equivalent to a minimum of 240 ECTS (4-year Bachelor\'s degree, 3-year Bachelor\'s degree + 1 year Master\'s degree) or certificate of enrollment indicating the approximate date of graduation.\nMinor (60 ECTS) in Business Studies including courses in: Corporate Finance and Investment Decisions, Accounting and Financial Statement Analysis, and Quantitative Methods for Finance.\nPlease note that for your initial application, we only request copies of documents. If your application is accepted, we will ask you to send certified digital copies, which you will need to present during orientation week. Further information on certified copies, broken down by nationality, is provided in the application form.\nTo ensure that GEM is the right fit for you, you may be asked to participate in an interview. You will be informed of the interview requirement after the admissions committee meeting.\n\nSpecific to the 2-year program Official copy of a Bachelor\'s degree equivalent to at least 180 ECTS or certificate of enrollment with an approximate date of graduation. Specific to the 1-year program Official copy of an undergraduate degree equivalent to a minimum of 240 ECTS (4-year Bachelor\'s degree, 3-year Bachelor\'s degree + 1 year Master\'s degree) or certificate of enrollment indicating the approximate date of graduation. Minor (60 ECTS) in Business Studies including courses in: Corporate Finance and Investment Decisions, Accounting and Financial Statement Analysis, and Quantitative Methods for Finance. Please note that for your initial application, we only request copies of documents. If your application is accepted, we will ask you to send certified digital copies, which you will need to present during orientation week. Further information on certified copies, broken down by nationality, is provided in the application form. To ensure that GEM is the right fit for you, you may be asked to participate in an interview. You will be informed of the interview requirement after the admissions committee meeting.\n\nTOEFL iBT: 80. TOEFL IELTS Academic/IELTS Indicator: 6.0','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1101,'01KWJDMF0HCBXAJ7NNJXNPTBEB',70,'MSc Financial Markets and Risk Management','masters',24,'English','Language requirement: TOEFL iBT: 80. TOEFL \nIELTS Academic/IELTS Indicator: 6.0\n\nToolkit source: non_exclusive / France Spain / row 329.','REQUIREMENTS / DOCUMENTS:\nSpecific to the 2-year program\nOfficial copy of an undergraduate degree equivalent to at least 180 ECTS or certificate of enrollment with an approximate date of graduation.                                                                                                                                                                                                           Specific to the 1-year program\nOfficial copy of a Bachelor\'s degree equivalent to a minimum of 240 ECTS (4-year Bachelor\'s, 3-year Bachelor\'s + 1-year Master\'s) or registration certificate indicating the approximate date of graduation.\n\nSpecific to the 2-year program Official copy of an undergraduate degree equivalent to at least 180 ECTS or certificate of enrollment with an approximate date of graduation. Specific to the 1-year program Official copy of a Bachelor\'s degree equivalent to a minimum of 240 ECTS (4-year Bachelor\'s, 3-year Bachelor\'s + 1-year Master\'s) or registration certificate indicating the approximate date of graduation.\n\nTOEFL iBT: 80. TOEFL IELTS Academic/IELTS Indicator: 6.0','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
