INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1104,'01KWJDMF0MPS8TD45AK8FFVN44',70,'MSc International Marketing and Business Development','masters',24,'English','Language requirement: TOEFL iBT: 80.\nIELTS Academic/IELTS 6.0\n\nToolkit source: non_exclusive / France Spain / row 332.','REQUIREMENTS / DOCUMENTS:\nSpecific to the 2-year program\nThe candidate\'s bachelor\'s degree must be equivalent to at least 180 ECTS (3-year bachelor\'s degree).                                                        The applicant must prove they hold the equivalent of 240 ECTS credits to enter the 1-year program:\na 4-year Bachelor\'s degree OR a 3-year Bachelor\'s degree plus at least one year of Master\'s studies\nApplicants must demonstrate that they have completed the equivalent of 60 ECTS credits (one year of study) in business studies.\nTo ensure that Grenoble School of Management is a good fit for you, you may be invited to an interview. You will be notified of the interview requirement after the admissions committee meeting.\nBachlelor - RNCP 6\n\nSpecific to the 2-year program The candidate\'s bachelor\'s degree must be equivalent to at least 180 ECTS (3-year bachelor\'s degree). The applicant must prove they hold the equivalent of 240 ECTS credits to enter the 1-year program: a 4-year Bachelor\'s degree OR a 3-year Bachelor\'s degree plus at least one year of Master\'s studies Applicants must demonstrate that they have completed the equivalent of 60 ECTS credits (one year of study) in business studies. To ensure that Grenoble School of Management is a good fit for you, you may be invited to an interview. You will be notified of the interview requirement after the admissions committee meeting.\n\nTOEFL iBT: 80. IELTS Academic/IELTS 6.0','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
