INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1124,'01KWJDMF11ABXZHZCN9YKHXWAG',72,'Bachelors Global BBA - Bachelor in Management','bachelors',48,'English','Language requirement: 2.5 GPA minimum\n\nToolkit source: non_exclusive / France Spain / row 360.','REQUIREMENTS / DOCUMENTS:\nHigh school graduate, High school + 1 year of study, High school + 2 years of study // Academic result - 2.5 GPA minimum                                                                                          Passport or ID card, Photo, CV, Cover letter\nHigh school transcript - last two years (predicted grades accepted)\nMinimum 2 different portfolios(any extra-curricular document such as art, music or sport certificates, recommendation letters, videos,hobbies, volunteer activities, etc)\nEnglish test certificate: TOEFL iBT®, IELTS, ICIMS (on request) or TOEIC®.\nMotivational interview\n\nHigh school graduate, High school + 1 year of study, High school + 2 years of study // Academic result - 2.5 GPA minimum Passport or ID card, Photo, CV, Cover letter High school transcript - last two years (predicted grades accepted) Minimum 2 different portfolios(any extra-curricular document such as art, music or sport certificates, recommendation letters, videos,hobbies, volunteer activities, etc) English test certificate: TOEFL iBT®, IELTS, ICIMS (on request) or TOEIC®. Motivational interview\n\n2.5 GPA minimum','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1125,'01KWJDMF15R3A7E9N75C67YWCV',73,'Bachelor in Management and Engineering Sciences','bachelors',48,'English','Language requirement: 6.0 Overall Bands\n\nToolkit source: non_exclusive / France Spain / row 361.','REQUIREMENTS / DOCUMENTS:\nAdmission requirements \nHolders of the International Baccalaureate or equivalent\nCompetition tests\nThe competitive entrance examination consists of an eligibility phase (application file) and an admission phase (interview).\nApplication file\nSchool reports from the final two years of secondary education (or equivalent).\nThe content and results in in mathematics, science subjects and foreign languages are taken into account.\nOptional letters of recommendation (maximum of two).\nAdmission phase\nIf the application is deemed admissible, the candidate will be invited to a motivational interview of the same type as for the national route.\nOral tests consist of a 20-minute video interview conducted in English, which includes a five-minute presentation of a personal experience that the candidate is proud of. The following criteria will be assessed\nTeam spirit and ability to work collaboratively\nCommitment and involvement in extracurricular activities\nOpen-mindedness and curiosity\nAlignment between the candidate\'s training project and the Bachelor\'s degree.​\n\nAdmission requirements Holders of the International Baccalaureate or equivalent Competition tests The competitive entrance examination consists of an eligibility phase (application file) and an admission phase (interview). Application file School reports from the final two years of secondary education (or equivalent). The content and results in in mathematics, science subjects and foreign languages are taken into account. Optional letters of recommendation (maximum of two). Admission phase If the application is deemed admissible, the candidate will be invited to a motivational interview of the same type as for the national route. Oral tests consist of a 20-minute video interview conducted in English, which includes a five-minute presentation of a personal experience that the candidate is proud of. The following criteria will be assessed Team spirit and ability to work collaboratively Commitment and involvement in extracurricular activities Open-mindedness and curiosity Alignment between the candidate’s training project and the Bachelor’s degree.​\n\n6.0 Overall Bands','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1126,'01KWJDMF15R3A7E9N75C67YWCX',73,'Grande Ecole / Master in Management','masters',24,'English','Toolkit source: non_exclusive / France Spain / row 362.','REQUIREMENTS / DOCUMENTS:\nCopy of passport\nDiploma (or certificate of attendance if the student has not yet graduated)\nUniversity grades transcripts\nWritten test scores (TAGE MAGE or GMAT or GRE or CAT​)\nTo send your official GMAT score to SKEMA, please use the following school codes: TQV-85-78\nOne of the following English language proficiency test score reports: TOEFL, TOEIC, IELTS, Duolingo, Cambridge, ICIMS.\nCV and cover letter\nA photo\nTwo letters of recommendation (academic or professional)\nThe application fee is €100 (non-reimbursable)  If the online application is judged satisfactory, candidates undergo an online interview. \nThe interview lasts about 30 minutes.\n\nCopy of passport Diploma (or certificate of attendance if the student has not yet graduated) University grades transcripts Written test scores (TAGE MAGE or GMAT or GRE or CAT​) To send your official GMAT score to SKEMA, please use the following school codes: TQV-85-78 One of the following English language proficiency test score reports: TOEFL, TOEIC, IELTS, Duolingo, Cambridge, ICIMS. CV and cover letter A photo Two letters of recommendation (academic or professional) The application fee is €100 (non-reimbursable) If the online application is judged satisfactory, candidates undergo an online interview. The interview lasts about 30 minutes.\n\n6.0 Overall Bands','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1127,'01KWJDMF163BMNGCD03HZC588C',73,'MSc Artificial Intelligence for Business Transformation','masters',24,'English','Language requirement: TOEFL IBT(71), TOEFL ITP(530), IELTS(6), TOEIC(810), Duolingo(105), Cambridge English Qualification®(165), ICIMS (61, on demand).\n\nToolkit source: non_exclusive / France Spain / row 363.','REQUIREMENTS / DOCUMENTS:\nRequirements - Two-Year​ MSc:\nEligible to apply: students who hold a three-year university degree or equivalent (180 ECTS credits or RNCP 6).\nA minimum of four months of professional experience (or internship) is required for the MSc Corporate Financial Management (CFM).                               Require​ments - MSc (one-year)*:\nEligible to apply: Students who hold a four-year university degree or equivalent (240 ECTS credits or RNCP 7) plus at least two months minimum of professional experience (or internship).\n- For the MSc Financial Markets and Investments, MSc Strategic Management and Consulting and MSc Corporate Financial Management, six months minimum of professional experience.\n- For the MSc Product Management & UX Design, MSc Entrepreneurship & Design for Sustainability, Italy doesn\'t recognise the professional qualifications such as RNCP titles.\n*In some cases, a three-year degree with three years minimum of professional experience after graduation can be accepted. Candidates with an Indian Bachelor degree are eligible for the One-year MSc if they have more than 3 years of work experience after graduation and for the Two-year MSc if they have less than 3 years of work experience.\n\nRequirements - Two-Year​ MSc: Eligible to apply: students who hold a three-year university degree or equivalent (180 ECTS credits or RNCP 6). A minimum of four months of professional experience (or internship) is required for the MSc Corporate Financial Management (CFM). Require​ments - MSc (one-year)*: Eligible to apply: Students who hold a four-year university degree or equivalent (240 ECTS credits or RNCP 7) plus at least two months minimum of professional experience (or internship). - For the MSc Financial Markets and Investments, MSc Strategic Management and Consulting and MSc Corporate Financial Management, six months minimum of professional experience. - For the MSc Product Management & UX Design, MSc Entrepreneurship & Design for Sustainability, Italy doesn’t recognise the professional qualifications such as RNCP titles. *In some cases, a three-year degree with three years minimum of professional experience after graduation can be accepted. Candidates with an Indian Bachelor degree are eligible for the One-year MSc if they have more than 3 years of work experience after graduation and for the Two-year MSc if they have less than 3 years of work experience.\n\nTOEFL IBT(71), TOEFL ITP(530), IELTS(6), TOEIC(810), Duolingo(105), Cambridge English Qualification®(165), ICIMS (61, on demand).','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1128,'01KWJDMF17KRS701SWAWFFY6Y9',73,'MSc Auditing, Management Accounting & Information Systems','masters',24,'English','Language requirement: TOEFL IBT(71), TOEFL ITP(530), IELTS(6), TOEIC(810), Duolingo(105), Cambridge English Qualification®(165), ICIMS(61, on demand).\n\nToolkit source: non_exclusive / France Spain / row 364.','REQUIREMENTS / DOCUMENTS:\nRequirements - Two-Year​ MSc:\nEligible to apply: students who hold a three-year university degree or equivalent.\nAnd students will be required to reach the necessary level for the MSc before moving to year two.\nRequire​ments - MSc (one-year):\nEligible to apply: students who hold a four-year university degree or equivalent + two months minimum of professional experience (for the MSc Financial Markets and Investments, this requirement is: a four-year degree + six months minimum of professional experience),\nStudents with the equivalent of a three-year degree in France, as well as a minimum of three years of professional experience.*                                                    *Candidates with an Indian bachelor\'s degree are eligible for the one-year MSc if they have more than three years of work experience and for the two-year MSc if they have less than three years of work experience.\n\nRequirements - Two-Year​ MSc: Eligible to apply: students who hold a three-year university degree or equivalent. And students will be required to reach the necessary level for the MSc before moving to year two. Require​ments - MSc (one-year): Eligible to apply: students who hold a four-year university degree or equivalent + two months minimum of professional experience (for the MSc Financial Markets and Investments, this requirement is: a four-year degree + six months minimum of professional exper