INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1155,'01KWJDMF1WV6Y82CS4SAW622RV',75,'Global BBA','bachelors',36,'English','Language requirement: IELTS: 6.0 or higher, TOEFL iBT: 84 or higher, Duolingo English Test: 100 or higher and TOEIC: 650 or higher\n\nToolkit source: non_exclusive / France Spain / row 481.','REQUIREMENTS / DOCUMENTS:\nregistration fee of €50\n\nComplete the online application (recommended by January 31). Once completed, you will pay the 100€ application fee by credit card. At a prearranged time, selected applicants will be invited for an interview via video-conference. The purpose of the interview is to confirm information provided in the application and to assess: Motivation to follow the program; Extra-curricular activities; Intellectual curiosity; Potential and ability to adapt to a new environment; Language proficiency in French and/or English.\n\nIELTS 6.0, TOEFL iBT 84, TOEIC 650, Duolingo 100','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1156,'01KWJDMF1XWVRF3RD6Z5DRKY97',75,'Bachelor\'s Degree in Communication','bachelors',36,'English','Language requirement: IELTS: 6.0 or higher, TOEFL iBT: 84 or higher, Duolingo English Test: 100 or higher and TOEIC: 650 or higher\n\nToolkit source: non_exclusive / France Spain / row 396.','REQUIREMENTS / DOCUMENTS:\nThe entrance exam for the first year is open to candidates who are in the process of obtaining or who have already obtained their Baccalaureate.\n\nThe entrance exam for the first year is open to candidates who are in the process of obtaining or who have already obtained their Baccalaureate.\n\nIELTS: 6.0 or higher, TOEFL iBT: 84 or higher, Duolingo English Test: 100 or higher and TOEIC: 650 or higher','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1157,'01KWJDMF1XWVRF3RD6Z5DRKY9A',75,'Bachelor\'s Degree in Communication - Post-Baccalaureate +2 Initial Training','bachelors',12,'English','Language requirement: IELTS: 6.0 or higher, TOEFL iBT: 84 or higher, Duolingo English Test: 100 or higher and TOEIC: 650 or higher\n\nToolkit source: non_exclusive / France Spain / row 397.','REQUIREMENTS / DOCUMENTS:\nBaccalaureate and post-baccalaureate grades: 6\nBackground (cover letter, professional/international experience, involvement in associations/sports): 6, Oral exams: 12, Motivational interview: 7, English oral exam: 5, Application fee for non-scholarship students: €50                                                                                                  Application file\n• Cover letter (1 page, single-sided) expressing your reasons for applying to the Audencia SciencesCom Program, your strengths for a career in the communication or media sector, and your stated career goals\n• CV (maximum one page)\n• Copy of your high school diploma\n• Copy of your high school transcript\n• Copies of diplomas/degrees obtained since high school\n• Copies of grades obtained for each year of higher education\nIn addition to these, the following supporting documents are required:\n• Copy of the 2025/2026 school certificate\n• Copy of your identity document\n• For scholarship candidates, a copy of the final award decision for a scholarship for the current school year, issued by the Rectorate or the CROUS\n• For candidates benefiting from the third-time measure, a copy of a medical certificate indicating the nature of the necessary accommodations (third time, printing in special characters, etc.), issued by the Departmental Commission for Special Education.\n\nBaccalaureate and post-baccalaureate grades: 6 Background (cover letter, professional/international experience, involvement in associations/sports): 6, Oral exams: 12, Motivational interview: 7, English oral exam: 5, Application fee for non-scholarship students: €50 Application file • Cover letter (1 page, single-sided) expressing your reasons for applying to the Audencia SciencesCom Program, your strengths for a career in the communication or media sector, and your stated career goals • CV (maximum one page) • Copy of your high school diploma • Copy of your high school transcript • Copies of diplomas/degrees obtained since high school • Copies of grades obtained for each year of higher education In addition to these, the following supporting documents are required: • Copy of the 2025/2026 school certificate • Copy of your identity document • For scholarship candidates, a copy of the final award decision for a scholarship for the current school year, issued by the Rectorate or the CROUS • For candidates benefiting from the third-time measure, a copy of a medical certificate indicating the nature of the necessary accommodations (third time, printing in special characters, etc.), issued by the Departmental Commission for Special Education.\n\nIELTS: 6.0 or higher, TOEFL iBT: 84 or higher, Duolingo English Test: 100 or higher and TOEIC: 650 or higher','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1158,'01KWJDMF1ZE656KCHVFPCWJ9FD',75,'Master\'s degree in Communication and Media (Bac+5) - apprenticeship','masters',24,'English','Language requirement: IELTS Academic - 6.0 to 6.5 // TOFEL IBT : Minimum of 84, TOEUC : Minimum 650-655 and Dualingo :- Minimum 100 to 110\n\nToolkit source: non_exclusive / France Spain / row 398.','REQUIREMENTS / DOCUMENTS:\nEntry into the first year of the Higher Education Diploma in Communication and Media (Bac+5) - apprenticeship is accessible by competitive examination open to all foreign students holding a diploma equivalency certificate or a Bac+3 qualification or having validated 180 ECTS within a recognized or certified diploma: BUT, Licence, etc. Documents Required - Cover Letter, CV, Proof of English Proficiency , Copy of you Bachelorate diploma or transcript, diplomas/ qualification - UG, copies of grades obtained in each year of higher education, identity documemnts\n3.0\n\nEntry into the first year of the Higher Education Diploma in Communication and Media (Bac+5) - apprenticeship is accessible by competitive examination open to all foreign students holding a diploma equivalency certificate or a Bac+3 qualification or having validated 180 ECTS within a recognized or certified diploma: BUT, Licence, etc. Documents Required - Cover Letter, CV, Proof of English Proficiency , Copy of you Bachelorate diploma or transcript, diplomas/ qualification - UG, copies of grades obtained in each year of higher education, identity documemnts\n\nIELTS Academic - 6.0 to 6.5 // TOFEL IBT : Minimum of 84, TOEUC : Minimum 650-655 and Dualingo :- Minimum 100 to 110','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
