INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1188,'01KWJDMF2RF5BP9QCRF2V83D2D',77,'Master in Finance','masters',12,'English','Language requirement: IELTS (6.0 minimum), TOEFL iBT (80 minimum), TOEIC (minimum 785)\n\nToolkit source: non_exclusive / France Spain / row 413.','REQUIREMENTS / DOCUMENTS:\nTo apply for admission in Year 1, applicants must hold either:\nA Bachelor\'s degree State-recognized as a Licence or a BAC+3 recognized by the French Ministry of Higher Education\nA credit equivalence attestation of at least 180 ECTS credits obtained in a State-recognized Grade de Master program\nTo apply for admission in Year 2, applicants must hold either:\nA 4-year State-recognized Bachelor\'s degree (equivalent to 240 ECTS credits)\nHave validated the first year of a State-recognized Master\'s Degree\nA credit equivalence attestation of at least 240 ECTS credits obtained in a State-recognized Grade de Master program\nYou can apply while being enrolled in the last year of the degree that makes you eligible for this program.\n\nTo apply for admission in Year 1, applicants must hold either: A Bachelor’s degree State-recognized as a Licence or a BAC+3 recognized by the French Ministry of Higher Education A credit equivalence attestation of at least 180 ECTS credits obtained in a State-recognized Grade de Master program To apply for admission in Year 2, applicants must hold either: A 4-year State-recognized Bachelor’s degree (equivalent to 240 ECTS credits) Have validated the first year of a State-recognized Master\'s Degree A credit equivalence attestation of at least 240 ECTS credits obtained in a State-recognized Grade de Master program You can apply while being enrolled in the last year of the degree that makes you eligible for this program.\n\nIELTS (6.0 minimum), TOEFL iBT (80 minimum), TOEIC (minimum 785)','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
