INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1243,'01KWJDMF3QWMD89P246RA37NCB',80,'Bachelor of Aeronautics','bachelors',36,'English','Language requirement: TOEIC, TOEFL, or IELTS. A B2 level is required .\n\nToolkit source: non_exclusive / France Spain / row 474.','REQUIREMENTS / DOCUMENTS:\nApplication review: CV, cover letter, school reports from the last 2 years, BAC transcript, copy of diploma(s) obtained.\nB1 and B2 students will take a multiple-choice test in mathematics and B3 students will take a multiple-choice test in English and logic.\nMotivation interview: essential to learn more about you, your study and career plans, your expectations, and to determine your suitability for our prestigious aerospace school.                                                                                                              Admission results are available within 15 days by email after the interview date.\n\nApplication review: CV, cover letter, school reports from the last 2 years, BAC transcript, copy of diploma(s) obtained. B1 and B2 students will take a multiple-choice test in mathematics and B3 students will take a multiple-choice test in English and logic. Motivation interview: essential to learn more about you, your study and career plans, your expectations, and to determine your suitability for our prestigious aerospace school. Admission results are available within 15 days by email after the interview date.\n\nTOEIC, TOEFL, or IELTS. A B2 level is required .','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1244,'01KWJDMF3R1AAQYYREWQ4NMW7C',80,'The MBA Engineering','masters',24,'English','Language requirement: TOEIC, TOEFL, or IELTS. A B2 level is required .\n\nToolkit source: non_exclusive / France Spain / row 475.','REQUIREMENTS / DOCUMENTS:\nAdmission requirements\n- Online multiple-choice test\n(several subjects depending on the entry level) - Oral summary and motivation: this is essential to learn more about the candidate, their study and career plan, their expectations and determine their suitability to join IPSA.                                                    Special conditions\n- Age requirement : You must be under 29 years old to be eligible for an apprenticeship contract.\n- Foreign candidates : To be eligible to sign an apprenticeship contract, foreign candidates must have already completed at least one year of studies in France as part of an initial training program and  reside in France .\n\nAdmission requirements – Online multiple-choice test (several subjects depending on the entry level) – Oral summary and motivation: this is essential to learn more about the candidate, their study and career plan, their expectations and determine their suitability to join IPSA. Special conditions – Age requirement : You must be under 29 years old to be eligible for an apprenticeship contract. – Foreign candidates : To be eligible to sign an apprenticeship contract, foreign candidates must have already completed at least one year of studies in France as part of an initial training program and reside in France .\n\nTOEIC, TOEFL, or IELTS. A B2 level is required .','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1245,'01KWJDMF3SP9DF3FJ49HB0SA8N',80,'MSc Aerospace Propulsion','masters',24,'English','Language requirement: TOEIC, TOEFL, or IELTS. A B2 level is required .\n\nToolkit source: non_exclusive / France Spain / row 476.','REQUIREMENTS / DOCUMENTS:\n-Online multiple-choice test\n(several subjects depending on the entry level). - Oral interview: this is essential to learn more about the candidate, their study and career plans, their expectations, and to determine their suitability for IPSA.\n- Application review\n\n-Online multiple-choice test (several subjects depending on the entry level). – Oral interview: this is essential to learn more about the candidate, their study and career plans, their expectations, and to determine their suitability for IPSA. – Application review\n\nTOEIC, TOEFL, or IELTS. A B2 level is required .','active',NULL,'2026-07-03 03:31:49','2026-07-13 23:24:35',NULL);
