INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1339,'01KWJDMF69K5VT4DEZZYWMH04E',85,'Cyber Security','masters',24,'English',NULL,'ELIGIBILITY:\nWe accept the following English language skills certificates*: \n\nIELTS (at least 6.5 points)\nTOEFL (at least 95 points)\nCambridge certificate (at least A grade overall)\n*Proof must not be older than two years. \n\n\nAlternative ways to prove your English language skills: \n\nCitizenship: If you are from a country where English is the official and educational language, your passport can serve as proof of English proficiency.\n\nGet in touch with our study advisors for more details.\n\n\nIU\'s English language requirements may differ from those set by your Embassy for visa applications. For your student visa application, you must follow the requirements specified by your local Embassy.\n\nREQUIREMENTS / DOCUMENTS:\nAcademic criteria:  \n\n Completed degree from a public or officially recognised university/higher education institution.\nAt least a \'satisfactory\' or Grade C equivalent earned in your previous degree.\nYour undergraduate studies must amount to 240 ECTS credits to begin a 60-ECTS MBA.\nYour undergraduate studies must amount to 210 ECTS to begin a 90-ECTS MBA  \nFurther Admission Opportunities:\n\n\nFor admission to the One-year MBA 60 ECTS MBA program or to the 90 ECTS MBA program, applicants with an undergraduate degree comprising 210 ECTS or 180 ECTS credits can compensate for missing ECTS credits (up to a maximum of 30 ECTS) by\n\nProviding proof of at least one year of full-time work experience to compensate for a maximum of 30 ECTS at the start of the study program.\n\n\nThis work experience must be acquired after completing the undergraduate degree. Recognition of knowledge and abilities acquired outside of higher education is possible in principle.\n\n\nProfessional Experience:  \n\nYou will need to have at least one year of professional work experience before starting an MBA programme (achieved after previous studies). \nYou can provide us with a translation of your employment contract and your pay slip or you can ask your company to fill out this form in English, sign it, apply the company stamp and send it to us','active',NULL,'2026-07-03 03:31:50','2026-07-03 03:31:50',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1340,'01KWJDMF6BRK11Z460MJKP15EP',85,'Data Science','masters',24,'English','Toolkit source: non_exclusive / Germany / row 96.','We accept the following English language skills certificates*: IELTS (at least 6.5 points) TOEFL (at least 95 points) Cambridge certificate (at least A grade overall) *Proof must not be older than two years. Alternative ways to prove your English language skills: Citizenship: If you are from a country where English is the official and educational language, your passport can serve as proof of English proficiency. Get in touch with our study advisors for more details. IU’s English language requirements may differ from those set by your Embassy for visa applications. For your student visa application, you must follow the requirements specified by your local Embassy.\n\nAcademic criteria: Completed degree from a public or officially recognised university/higher education institution. At least a ‘satisfactory’ or Grade C equivalent earned in your previous degree. Your undergraduate studies must amount to 240 ECTS credits to begin a 60-ECTS MBA. Your undergraduate studies must amount to 210 ECTS to begin a 90-ECTS MBA Further Admission Opportunities: For admission to the One-year MBA 60 ECTS MBA program or to the 90 ECTS MBA program, applicants with an undergraduate degree comprising 210 ECTS or 180 ECTS credits can compensate for missing ECTS credits (up to a maximum of 30 ECTS) by Providing proof of at least one year of full-time work experience to compensate for a maximum of 30 ECTS at the start of the study program. This work experience must be acquired after completing the undergraduate degree. Recognition of knowledge and abilities acquired outside of higher education is possible in principle. Professional Experience: You will need to have at least one year of professional work experience before starting an MBA programme (achieved after previous studies). You can provide us with a translation of your employment contract and your pay slip or you can ask your company to fill out this form in English, sign it, apply the company stamp and send it to us','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
