INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1375,'01KWJDMF7BHKB7DQ78CH7J0XCF',87,'Master in Leading Hotel Transformation','masters',48,'English','Toolkit source: non_exclusive / Netherlands / row 5.','ELIGIBILITY:\n1. A foreign Bachelor\'s degree must be equivalent to at least a Dutch Professional Bachelor\'s degree from an accredited institution.                                  2. IELTS*: Academic test: minimum overall band score of 6.0, and minimum subscore of 6.0 for speaking\n\nREQUIREMENTS / DOCUMENTS:\n• NVAO accredited bachelor degree or equivalent (Dutch funded bachelor degree e.g.)\n• Minimum of 12 months relevant work experience in the service-related industry.\n• C1 English level skills, both written and oral.\n• Pre-masters or GMAT tests are not required.                                       -------------------------------------------------------------------A Bachelor\'s degree (Dutch or international) in Hotel Management or a related field, such as Hospitality Management, Facility Management, Tourism Management, or Leisure & Events Management.\nForeign Degree Equivalency: A foreign Bachelor\'s degree must be equivalent to at least a Dutch Professional Bachelor\'s degree from an accredited institution. Hotelschool The Hague may submit your academic records to Nuffic for evaluation and advice regarding your prior or current education. As per our policy, Nuffic\'s advice leads in the decision-making process.\nIf you have not yet obtained your Bachelor\'s degree at the time of application, you are asked to upload your most recent official grade list\n\n1. A foreign Bachelor\'s degree must be equivalent to at least a Dutch Professional Bachelor\'s degree from an accredited institution. 2. IELTS*: Academic test: minimum overall band score of 6.0, and minimum subscore of 6.0 for speaking\n\n• NVAO accredited bachelor degree or equivalent (Dutch funded bachelor degree e.g.) • Minimum of 12 months relevant work experience in the service-related industry. • C1 English level skills, both written and oral. • Pre-masters or GMAT tests are not required. -------------------------------------------------------------------A Bachelor\'s degree (Dutch or international) in Hotel Management or a related field, such as Hospitality Management, Facility Management, Tourism Management, or Leisure & Events Management. Foreign Degree Equivalency: A foreign Bachelor\'s degree must be equivalent to at least a Dutch Professional Bachelor\'s degree from an accredited institution. Hotelschool The Hague may submit your academic records to Nuffic for evaluation and advice regarding your prior or current education. As per our policy, Nuffic\'s advice leads in the decision-making process. If you have not yet obtained your Bachelor’s degree at the time of application, you are asked to upload your most recent official grade list','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1376,'01KWJDMF7CZD14656MXXXVD9PD',87,'MBA in International Hospitality Management','masters',48,'English','Toolkit source: non_exclusive / Netherlands / row 6.','ELIGIBILITY:\n1. Related Bachelor Degree (GMAT may be required)\n2. Professional leadership work experience (minimum 1 year cumulative and full-time) in the service industry.                                                                          3. C1 English Language Skills (TOEFL, IELTS and or Cambridge Certificate\n\n1. Related Bachelor Degree (GMAT may be required) 2. Professional leadership work experience (minimum 1 year cumulative and full-time) in the service industry. 3. C1 English Language Skills (TOEFL, IELTS and or Cambridge Certificate\n\n• NVAO accredited bachelor degree or equivalent (Dutch funded bachelor degree e.g.) • Minimum of 12 months relevant work experience in the service-related industry. • C1 English level skills, both written and oral. • Pre-masters or GMAT tests are not required. -------------------------------------------------------------------A Bachelor\'s degree (Dutch or international) in Hotel Management or a related field, such as Hospitality Management, Facility Management, Tourism Management, or Leisure & Events Management. Foreign Degree Equivalency: A foreign Bachelor\'s degree must be equivalent to at least a Dutch Professional Bachelor\'s degree from an accredited institution. Hotelschool The Hague may submit your academic records to Nuffic for evaluation and advice regarding your prior or current education. As per our policy, Nuffic\'s advice leads in the decision-making process. If you have not yet obtained your Bachelor’s degree at the time of application, you are asked to upload your most recent official grade list','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
