INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1434,'01KWJDMF8ASX7P4P2147SEYHFB',89,'MSc Clinical Psychology','masters',36,'English','Toolkit source: non_exclusive / Cyprus / row 56.','ELIGIBILITY:\n1. The minimum general requirement for admission to the post-graduate degree programme is a bachelor\'s degree in Psychology (or expected, to be completed before the commencement of studies) from a recognized university with a GPA of at least 3.0 or a Second-Class Upper Division Honors (British Degrees) or 7.5 (Greek Degrees).                                              2. IELTS 6.5 and above\n\n1. The minimum general requirement for admission to the post-graduate degree programme is a bachelor’s degree in Psychology (or expected, to be completed before the commencement of studies) from a recognized university with a GPA of at least 3.0 or a Second-Class Upper Division Honors (British Degrees) or 7.5 (Greek Degrees). 2. IELTS 6.5 and above','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1435,'01KWJDMF8ASX7P4P2147SEYHFD',89,'MSc.Counseling Psychology','masters',30,'English','Toolkit source: non_exclusive / Cyprus / row 57.','ELIGIBILITY:\nThe minimum general requirement for admission to the post-graduate degree programme is a Bachelor Degree from a recognised university with a GPA of at least 3.0 or a Second Class Upper Division Honors (British Degrees) or 7.5 (Greek Degrees).\nIn addition to the above, applicants must also satisfy the following requirements:\nProspective candidates are also evaluated for admission on the basis of previous clinical and research experience, any other postgraduate qualifications in the area of Psychology, academic references and a personal statement.\nFinally, admission to the program is also evaluated on the basis of the candidates\' performance during an admissions interview.\nOnce admitted, students whose native language is not Greek will be required to demonstrate proficiency in the Greek language at the B1 level (as per the Common European Framework of Reference for Languages) before advancing to the Clinical Practicum Seminar (in the Spring semester of their second year). IELTS 6.5 and above\n\nThe minimum general requirement for admission to the post-graduate degree programme is a Bachelor Degree from a recognised university with a GPA of at least 3.0 or a Second Class Upper Division Honors (British Degrees) or 7.5 (Greek Degrees). In addition to the above, applicants must also satisfy the following requirements: Prospective candidates are also evaluated for admission on the basis of previous clinical and research experience, any other postgraduate qualifications in the area of Psychology, academic references and a personal statement. Finally, admission to the program is also evaluated on the basis of the candidates’ performance during an admissions interview. Once admitted, students whose native language is not Greek will be required to demonstrate proficiency in the Greek language at the B1 level (as per the Common European Framework of Reference for Languages) before advancing to the Clinical Practicum Seminar (in the Spring semester of their second year). IELTS 6.5 and above','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
