INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1438,'01KWJDMF8CKQNY5J6FQZYG4YRY',89,'Law - LLM','masters',18,'English','Toolkit source: non_exclusive / Cyprus / row 60.','ELIGIBILITY:\nThe minimum general requirement for admission to the post-graduate degree programme is a Bachelor Degree from a recognised university. More specifically for the LLM; prospective students should be holders of a Bachelor degree in Law or in another relevant field\nThe program admits students in the Fall and Spring semesters. Applications for admission to the program will be considered only from candidates that fulfill the minimum entrance criteria as described below:\nProspective students should be holders of a Bachelor degree in Law or in another relevant field\nTwo recommendation letters and a letter by the prospective student expressing his/her interest in following the program, sketching out his/her research profile and mentioning his/her expectations from the programme, regarding his/her personal development and professional perspectives.\nIELTS 6.5 and abvoe\n\nThe minimum general requirement for admission to the post-graduate degree programme is a Bachelor Degree from a recognised university. More specifically for the LLM; prospective students should be holders of a Bachelor degree in Law or in another relevant field The program admits students in the Fall and Spring semesters. Applications for admission to the program will be considered only from candidates that fulfill the minimum entrance criteria as described below: Prospective students should be holders of a Bachelor degree in Law or in another relevant field Two recommendation letters and a letter by the prospective student expressing his/her interest in following the program, sketching out his/her research profile and mentioning his/her expectations from the programme, regarding his/her personal development and professional perspectives. IELTS 6.5 and abvoe','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1439,'01KWJDMF8CKQNY5J6FQZYG4YS0',89,'MA International Relations and Eastern Mediterranean Studies','masters',18,'English','Toolkit source: non_exclusive / Cyprus / row 61.','ELIGIBILITY:\nThe minimum general requirement for admission to the post-graduate degree programme is a Bachelor Degree from a recognised university.\nIn addition to the above, applicants must also satisfy the following requirements/submit the following documents: A CV of the prospective student.\nΤwo recommendation letters.\nA personal statement by the prospective student expressing his/her interest in following the program.\nProficient knowledge of English (see below)\nKnowledge of more than one foreign language will be considered an advantage. IELTS 6.5 and abvoe\n\nThe minimum general requirement for admission to the post-graduate degree programme is a Bachelor Degree from a recognised university. In addition to the above, applicants must also satisfy the following requirements/submit the following documents: A CV of the prospective student. Τwo recommendation letters. A personal statement by the prospective student expressing his/her interest in following the program. Proficient knowledge of English (see below) Knowledge of more than one foreign language will be considered an advantage. IELTS 6.5 and abvoe','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
