INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1467,'01KWJDMF8TVZH3T31WRK66C0D1',89,'PhD Medical Sciences','masters',36,'English','Toolkit source: non_exclusive / Cyprus / row 90.','ELIGIBILITY:\nEligible Candidates should hold (or hold by the time that their registration on the programme is expected to commence) recognized degrees; a Bachelor\'s and a Master\'s degree (or equivalent) for entry to a Doctoral Degree. Please note that a Medical degree is the minimum entry requirement for the Medical School\'s doctoral programme. and IELTS  7 overall and with a minimum score of 7 in writing or TOEFL iBT with a score of 94 overall and a minimum score of 27 in Writing\n\nEligible Candidates should hold (or hold by the time that their registration on the programme is expected to commence) recognized degrees; a Bachelor’s and a Master’s degree (or equivalent) for entry to a Doctoral Degree. Please note that a Medical degree is the minimum entry requirement for the Medical School’s doctoral programme. and IELTS 7 overall and with a minimum score of 7 in writing or TOEFL iBT with a score of 94 overall and a minimum score of 27 in Writing','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
