INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1481,'01KWJDMF96ADPP8QKYBF7GKCAZ',91,'Business Administration - Diploma','diploma',24,'English','Toolkit source: non_exclusive / Cyprus / row 107.','ELIGIBILITY:\nAdmission Fee of €150.\n\nREQUIREMENTS / DOCUMENTS:\nAn average score of at least of 5.0 in the IELTS examination.\nA score of at least 71 in the TOEFL Internet Based Test (TOEFL iBT).\nA score of at least 5.5 in the Password Skills Test Plus.\nA grade of at least D in the IGCSE English language as a second language examination.\nA pass grade in Anglia Intermediate General English Examination.\n\nApplicants for an undergraduate program of study (Certificate, Diploma or Bachelor Degree) must fulfill the following admission criteria: A recognized Secondary (High) School Leaving Certificate (i.e. 12 or 11 years of education depending on the country of origin) or equivalent qualifications (e.g. GCE “A” levels).\n\nAn average score of at least of 5.0 in the IELTS examination. A score of at least 71 in the TOEFL Internet Based Test (TOEFL iBT). A score of at least 5.5 in the Password Skills Test Plus. A grade of at least D in the IGCSE English language as a second language examination. A pass grade in Anglia Intermediate General English Examination.\n\nAdmission Fee of €150.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
