INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1561,'01KWJDMFB63DHZZP4T4J0QQ5Y9',96,'Clinical Dietetics (MSc)','masters',48,'English','Toolkit source: non_exclusive / Cyprus / row 205.','ELIGIBILITY:\nSeptember\n\nREQUIREMENTS / DOCUMENTS:\nSix-year secondary school diploma\nA degree from a recognized university or college or proof of expected graduation\nDetailed Degree Score\nTwo (2) letters of recommendation in a sealed envelope\nPersonal interview with the student\nProof of English language proficiency\n\nApplications for the postgraduate study program \'Clinical Dietetics\' have begun. Holders of a degree in \'Dietetics & Nutrition\' are accepted. Graduates of related degrees such as Biologists, Nurses, Food Technologists and similar degrees are also accepted, on the condition that they attend the preparatory courses to join the program.\n\nSix-year secondary school diploma A degree from a recognized university or college or proof of expected graduation Detailed Degree Score Two (2) letters of recommendation in a sealed envelope Personal interview with the student Proof of English language proficiency\n\nSeptember','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
