INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1595,'01KWJDMFBPK07HFMCW73D53YW5',98,'Accounting and Finance','bachelors',48,'English','Toolkit source: non_exclusive / Cyprus / row 244.','ELIGIBILITY:\nSuccessful completion of a university Foundation program or an equivalent qualification;\n\nExamples of acceptable English language qualifications, equivalent to B2 English Level of the Common European Framework, for admission, include:  IELTS (Bands 5.5 - 6)\n\nREQUIREMENTS / DOCUMENTS:\nIELTS: ≥ 5.0\n\nTOEFL iBT: ≥ 71\n\nPearson PTE Academic: ≥ 58\n\nIGCSE/GCSE English: D+\n\nIB English (Standard Level): 5\n\nIB English (Higher Level): 4\n\nGCE English Language: D+\n\nMichigan ECCE: ≥ 52\n\nAnglia Intermediate\n\nUniversity of Cambridge FCE\n\nPassword Skills Plus: 5.5+\n\nSAT Evidence-Based Reading & Writing: ≥ 530\n\nCompletion of a six-year secondary education (Apolyterion) recognized by the Cyprus or Greek Ministry of Education, or GCE qualifications: 5 subjects including 2 at Advanced Level plus Ordinary Level pass in English, or 4 subjects including 3 at Advanced Level plus Ordinary Level pass in English, or Completion of a university Foundation programme or Completion of 12 years of schooling from an accredited secondary institution with English competency evidence\n\nIELTS: ≥ 5.0 TOEFL iBT: ≥ 71 Pearson PTE Academic: ≥ 58 IGCSE/GCSE English: D+ IB English (Standard Level): 5 IB English (Higher Level): 4 GCE English Language: D+ Michigan ECCE: ≥ 52 Anglia Intermediate University of Cambridge FCE Password Skills Plus: 5.5+ SAT Evidence-Based Reading & Writing: ≥ 530\n\nSuccessful completion of a university Foundation program or an equivalent qualification; Examples of acceptable English language qualifications, equivalent to B2 English Level of the Common European Framework, for admission, include: IELTS (Bands 5.5 – 6)','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
