INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1601,'01KWJDMFBRW0CD0RT1C33ZFTGB',98,'MSc in Corporate Finance with Corporate Governance','masters',18,'English','Toolkit source: non_exclusive / Cyprus / row 251.','ELIGIBILITY:\nIELTS (Bands 5.5 - 6) or an equivalent Degree from a recognized academic institution.\nAt least 2 years of  work experience.\nPersonal statement.\nProficiency in English language, unless they hold a degree from an English speaking institution.\nTwo references from academics or people who are familiar with the work of the candidate.\nApplicants will be invited for a personal interview.\n\nREQUIREMENTS / DOCUMENTS:\nFor general postgraduate: IELTS 6.0 or equivalent\n\nFor MBA (example): IELTS ≥ 6.5, TOEFL ≥ 550 (paper‑based) or equivalent tests (Required unless applicant holds a degree from an English-medium institution)                                                                           Personal statement or academic statement outlining goals and motivations \nTwo references (academic or professional) \nCurriculum Vitae / Resume\nReport of Research Interests (in some programmes) \nInterview with the Admissions Committee (especially for MBA and related degrees)\n\nA recognized Bachelor’s degree (UG diploma) from an accredited institution At least 2 years of work experience (especially in managerial or supervisory roles is recommended for MBA programmes)\n\nFor general postgraduate: IELTS 6.0 or equivalent For MBA (example): IELTS ≥ 6.5, TOEFL ≥ 550 (paper‑based) or equivalent tests (Required unless applicant holds a degree from an English-medium institution) Personal statement or academic statement outlining goals and motivations Two references (academic or professional) Curriculum Vitae / Resume Report of Research Interests (in some programmes) Interview with the Admissions Committee (especially for MBA and related degrees)\n\nIELTS (Bands 5.5 – 6) or an equivalent Degree from a recognized academic institution. At least 2 years of work experience. Personal statement. Proficiency in English language, unless they hold a degree from an English speaking institution. Two references from academics or people who are familiar with the work of the candidate. Applicants will be invited for a personal interview.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1602,'01KWJDMFBSGKM297RJ30XNG46K',98,'MBA, Master of Business Administration (English)','masters',18,'English','Toolkit source: non_exclusive / Cyprus / row 252.','ELIGIBILITY:\nIELTS (6.5. or higher) or TOEFL (550+) or GCE Ordinary level (Grade C or above). Degree from a recognized academic institution.\nAt least 2 years of  work experience.\nPersonal statement.\nProficiency in English language, unless they hold a degree from an English speaking institution.\nTwo references from academics or people who are familiar with the work of the candidate.\nApplicants will be invited for a personal interview.\n\nA recognized Bachelor’s degree (UG diploma) from an accredited institution At least 2 years of work experience (especially in managerial or supervisory roles is recommended for MBA programmes)\n\nFor general postgraduate: IELTS 6.0 or equivalent For MBA (example): IELTS ≥ 6.5, TOEFL ≥ 550 (paper‑based) or equivalent tests (Required unless applicant holds a degree from an English-medium institution) Personal statement or academic statement outlining goals and motivations Two references (academic or professional) Curriculum Vitae / Resume Report of Research Interests (in some programmes) Interview with the Admissions Committee (especially for MBA and related degrees)\n\nIELTS (6.5. or higher) or TOEFL (550+) or GCE Ordinary level (Grade C or above). Degree from a recognized academic institution. At least 2 years of work experience. Personal statement. Proficiency in English language, unless they hold a degree from an English speaking institution. Two references from academics or people who are familiar with the work of the candidate. Applicants will be invited for a personal interview.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:36',NULL);
