INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1688,'01KWJDMFD2DW3ECA9ZPCWJX2QV',103,'BSc Hotel Administration','bachelors',48,'English','Toolkit source: non_exclusive / Cyprus / row 382.','ELIGIBILITY:\nFall Semester: Classes for Fall 2024 began on October 14, 2024.\n\nSpring Semester: Classes for Spring 2025 will begin on February 17, 2025.\n\nSummer Semester: Classes for Summer 2025 will begin on June 16, 2025.\n\nREQUIREMENTS / DOCUMENTS:\nA six‐year Secondary or High School Leaving Certificate or an equivalent qualification.\nProof of English Language Proficiency.\n\nIELTS: minimum Grade 5 TOEFL IBT: minimum 71 marks Password Skills Plus Test: min. 5.5 Anglia Examinations: Intermediate Michigan Language Assessment: ECCE (52) Cambridge GCE AS Level in English Language: min. C Cambridge GCE A Levels: min. D Cambridge IGCE or GCSE English as a First Language: min. E Cambridge IGCE or GCSE English as a Second Language: min. D University of Cambridge Exams: B2 First (FCE) PEARSON PTE Academic: 58 SAT Evidence-Based Reading and Writing (EBRW):530 Common European Framework of Reference Languages (CEFR): B1 IB English A: Literature SL & HL:4 IB English B: High Level (HL): 4 IB English B Standard Level (SL): 5\n\nA six‐year Secondary or High School Leaving Certificate or an equivalent qualification. Proof of English Language Proficiency.\n\nFall Semester: Classes for Fall 2024 began on October 14, 2024. Spring Semester: Classes for Spring 2025 will begin on February 17, 2025. Summer Semester: Classes for Summer 2025 will begin on June 16, 2025.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1689,'01KWJDMFD3QZN4D5CZMSJF7W56',103,'CERTIFICATE - Cruise Ship Hospitality Operations','certificate',12,'English','Toolkit source: non_exclusive / Cyprus / row 384.','REQUIREMENTS / DOCUMENTS:\nMinimum 50 % on high school leaving certificate.\nProof of English Language Proficiency.\n\nIELTS: minimum Grade 5 TOEFL IBT: minimum 71 marks Password Skills Plus Test: min. 5.5 Anglia Examinations: Intermediate Michigan Language Assessment: ECCE (52) Cambridge GCE AS Level in English Language: min. C Cambridge GCE A Levels: min. D Cambridge IGCE or GCSE English as a First Language: min. E Cambridge IGCE or GCSE English as a Second Language: min. D University of Cambridge Exams: B2 First (FCE) PEARSON PTE Academic: 58 SAT Evidence-Based Reading and Writing (EBRW):530 Common European Framework of Reference Languages (CEFR): B1 IB English A: Literature SL & HL:4 IB English B: High Level (HL): 4 IB English B Standard Level (SL): 5\n\nMinimum 50 % on high school leaving certificate. Proof of English Language Proficiency.\n\nFall Semester: Classes for Fall 2024 began on October 14, 2024. Spring Semester: Classes for Spring 2025 will begin on February 17, 2025. Summer Semester: Classes for Summer 2025 will begin on June 16, 2025.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1690,'01KWJDMFD3QZN4D5CZMSJF7W58',103,'English Language Foundation Program','diploma',12,'English','Toolkit source: non_exclusive / Cyprus / row 385.','REQUIREMENTS / DOCUMENTS:\nA six‐year Secondary or High School Leaving Certificate or an equivalent qualification.\nProof of English Language Proficiency.\n\nIELTS: minimum Grade 4.0 TOEFL IBT: minimum 42 marks Password Skills Plus Test: min. 4.0 Michigan Language Assessment: ECCE (40) Cambridge IGCE or GCSE English as a First Language: min. F Cambridge IGCE or GCSE English as a Second Language: min. E PEARSON PTE Academic: 43 SAT Evidence-Based Reading and Writing (EBRW):450 Common European Framework of Reference Languages (CEFR): B1 IB English B: High Level (HL): 3 IB English B Standard Level (SL): 4\n\nA six‐year Secondary or High School Leaving Certificate or an equivalent qualification. Proof of English Language Proficiency.\n\nFall Semester: Classes for Fall 2024 began on October 14, 2024. Spring Semester: Classes for Spring 2025 will begin on February 17, 2025. Summer Semester: Classes for Summer 2025 will begin on June 16, 2025.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1691,'01KWJDMFD49DN9NTWBYZFY7R4B',104,'BSc in Business Administration','bachelors',48,'English','Toolkit source: non_exclusive / Cyprus / row 388.','REQUIREMENTS / DOCUMENTS:\ncompleted application form.\nCertified results for all the examinations mentioned in the application form and / or confirmation of the award of the student\'s degree.\nEvidence of knowledge of the English language.\nOriginal or duplicate of the Secondary Education Certificate (Apolyterion) or an equivalent diploma to that of the Lyceum Certificate.\nA personal statement of interest in undergraduate studies.\nInternational students must submit to the Admissions Office details of their financial status as proof of their ability to pay the tuition fees for their studies, e.g. a bank account statement.\n\nUniversity of Cambridge exams B2 (FCE) IELTS 5 TOEFL (IBT) 71 IB English B Standard Level (SL) 5 IB English A: Literature SL & HL 4 Cambridge IGCSE or GCSE English as a second language D Cambridge IGCSE or GCSE English as a first language E Cambridge GCE English A levels D Cambridge GCE AS level English language C Anglia Examinations Intermediate Password Skills Plus Test 5.5 Michigan Language Assessment ECCE (52) Pearson PTE Academic 58 Common European Framework of Reference for Languages (CERF) B1\n\ncompleted application form. Certified results for all the examinations mentioned in the application form and / or confirmation of the award of the student\'s degree. Evidence of knowledge of the English language. Original or duplicate of the Secondary Education Certificate (Apolyterion) or an equivalent diploma to that of the Lyceum Certificate. A personal statement of interest in undergraduate studies. International students must submit to the Admissions Office details of their financial status as proof of their ability to pay the tuition fees for their studies, e.g. a bank account statement.\n\nThe academic year is divided into a Fall semester (October-January) and a Spring semester (February-June). Admissions for new students are made in September and January. Applicants can apply at any time during the year.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1692,'01KWJDMFD49DN9NTWBYZFY7R4D',104,'Master in Business Administration, MBA, Full-time','masters',12,'English','Toolkit source: non_exclusive / Cyprus / row 390.','University of Cambridge exams B2 (FCE) IELTS 5 TOEFL (IBT) 71 IB English B Standard Level (SL) 5 IB English A: Literature SL & HL 4 Cambridge IGCSE or GCSE English as a second language D Cambridge IGCSE or GCSE English as a first language E Cambridge GCE English A levels D Cambridge GCE AS level English language C Anglia Examinations Intermediate Password Skills Plus Test 5.5 Michigan Language Assessment ECCE (52) Pearson PTE Academic 58 Common European Framework of Reference for Languages (CERF) B1\n\ncompleted application form. Certified results for all the examinations mentioned in the application form and / or confirmation of the award of the student\'s degree. Evidence of knowledge of the English language. Original or duplicate of the Secondary Education Certificate (Apolyterion) or an equivalent diploma to that of the Lyceum Certificate. A personal statement of interest in undergraduate studies. International students must submit to the Admissions Office details of their financial status as proof of their ability to pay the tuition fees for their studies, e.g. a bank account statement.\n\nThe academic year is divided into a Fall semester (October-January) and a Spring semester (February-June). Admissions for new students are made in September and January. Applicants can apply at any time during the year.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
