INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1709,'01KWJDMFDCVFYMYQ5V3JKCZJFH',107,'Culinary Arts Management','bachelors',48,'English','Toolkit source: non_exclusive / Cyprus / row 417.','REQUIREMENTS / DOCUMENTS:\nCompleted secondary education (high school diploma or equivalent)\n\nMinimum of 12 years of schooling\n\nA recognized national certificate allowing access to higher education (e.g. A-levels, IB, national school-leaving certificate)\n\nIELTS: 5.0 or higher TOEFL iBT: 71 IGCSE / GCSE English: Minimum grade E Cambridge First Certificate (FCE): B2 IB (English B or A): 4 or 5 depending on level PTE Academic: 58 CEFR (Common European Framework): B1 minimum Password English Test / Anglia / ECCE: Equivalent to B1–B2 level Diploma Programme Diploma Programme Completed Application Form (online or PDF) Passport or National ID copy High school diploma or equivalent (for Bachelor’s/Diploma) Academic transcripts (grades of previous studies) Passport-sized photographs (usually 2) Proof of English language proficiency (if applicable – see below) Medical certificate (for some programmes like Culinary Arts or Aesthetics) Application fee payment receipt (if required\n\nCompleted secondary education (high school diploma or equivalent) Minimum of 12 years of schooling A recognized national certificate allowing access to higher education (e.g. A-levels, IB, national school-leaving certificate)\n\nFall Semester (Primary Intake)- October Spring Semester (Secondary Intake) - Feb','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
