INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1726,'01KWJDMFDR5AY3EY8D8RNCK8XX',109,'Programme','bachelors',NULL,'English',NULL,'ELIGIBILITY:\nProspective students must demonstrate at least B2-level English proficiency. This can be proven through one of the following:\n\nAchieving a score of over 60% on an advanced-level English final exam,\nSubmitting an official document from their secondary school stating that the language of instruction was English,\nNative speaker of English (based on passport citizenship),\nProviding one of the accepted English language certificates listed below:\nThe International English Language Testing System (IELTS, General) with a minimum overall score of 6.0 points \nThe Test of English as a Foreign Language (TOEFL) with a minimum score of 72 in the iBT version\nCambridge Certificate with a minimum score of 169 (B2 First, B2 Business Vantage)\nInternational GCSE English as a Second Language with a score of C or higher on extended curriculum                                                                                               London University GCE O level Syllabus, minimum B in English Language\nPearson Test of English Academic (PTE Academic) with a minimum score of 50\nEUROEXAM B2 level certificate\nA B2 level English language certificate\nLCCI certificate with a minimum score of 60\nDuolingo English Test with a minimum score of 105\nHungarian high-level English language baccalaureate exam with a minimum result of 60%\nOxford Test of English Advanced: Overall score min. 111\nCELPIP with a minimum score of 7\nCAEL with a minimum score of 50\nAs a one-time special offer, IBS will cover the fee for the Duolingo English Test for applicants who do not have any of the other accepted English language certifications. To qualify, applicants must present their Duolingo test result to IBS and begin their studies in September 2025. The test fee will be deducted from the tuition fee payment.\n\nREQUIREMENTS / DOCUMENTS:\nHigh school diploma and a certified English translation of your high school diploma if it is not in English.','active',NULL,'2026-07-03 03:31:50','2026-07-03 03:31:50',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1727,'01KWJDMFDR5AY3EY8D8RNCK8Y2',109,'BSc in Corporate Finance','bachelors',36,'English','Toolkit source: non_exclusive / Hungary / row 4.','Prospective students must demonstrate at least B2-level English proficiency. This can be proven through one of the following: Achieving a score of over 60% on an advanced-level English final exam, Submitting an official document from their secondary school stating that the language of instruction was English, Native speaker of English (based on passport citizenship), Providing one of the accepted English language certificates listed below: The International English Language Testing System (IELTS, General) with a minimum overall score of 6.0 points The Test of English as a Foreign Language (TOEFL) with a minimum score of 72 in the iBT version Cambridge Certificate with a minimum score of 169 (B2 First, B2 Business Vantage) International GCSE English as a Second Language with a score of C or higher on extended curriculum London University GCE O level Syllabus, minimum B in English Language Pearson Test of English Academic (PTE Academic) with a minimum score of 50 EUROEXAM B2 level certificate A B2 level English language certificate LCCI certificate with a minimum score of 60 Duolingo English Test with a minimum score of 105 Hungarian high-level English language baccalaureate exam with a minimum result of 60% Oxford Test of English Advanced: Overall score min. 111 CELPIP with a minimum score of 7 CAEL with a minimum score of 50 As a one-time special offer, IBS will cover the fee for the Duolingo English Test for applicants who do not have any of the other accepted English language certifications. To qualify, applicants must present their Duolingo test result to IBS and begin their studies in September 2025. The test fee will be deducted from the tuition fee payment.\n\nHigh school diploma and a certified English translation of your high school diploma if it is not in English.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1728,'01KWJDMFDSC2WYETMGG8XGGJP6',109,'BSc in Business Management with specialisations: AI & Data Analytics, Arts, Diplomacy & International Relations, HRM & Business Psychology, Marketing, Tourism','bachelors',36,'English','Toolkit source: non_exclusive / Hungary / row 5.','Prospective students must demonstrate at least B2-level English proficiency. This can be proven through one of the following: Achieving a score of over 60% on an advanced-level English final exam, Submitting an official document from their secondary school stating that the language of instruction was English, Native speaker of English (based on passport citizenship), Providing one of the accepted English language certificates listed below: The International English Language Testing System (IELTS, General) with a minimum overall score of 6.0 points The Test of English as a Foreign Language (TOEFL) with a minimum score of 72 in the iBT version Cambridge Certificate with a minimum score of 169 (B2 First, B2 Business Vantage) International GCSE English as a Second Language with a score of C or higher on extended curriculum London University GCE O level Syllabus, minimum B in English Language Pearson Test of English Academic (PTE Academic) with a minimum score of 50 EUROEXAM B2 level certificate A B2 level English language certificate LCCI certificate with a minimum score of 60 Duolingo English Test with a minimum score of 105 Hungarian high-level English language baccalaureate exam with a minimum result of 60% Oxford Test of English Advanced: Overall score min. 111 CELPIP with a minimum score of 7 CAEL with a minimum score of 50 As a one-time special offer, IBS will cover the fee for the Duolingo English Test for applicants who do not have any of the other accepted English language certifications. To qualify, applicants must present their Duolingo test result to IBS and begin their studies in September 2025. The test fee will be deducted from the tuition fee payment.\n\nHigh school diploma and a certified English translation of your high school diploma if it is not in English.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
