INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1747,'01KWJDMFEEASA1Q1H3F7MG7798',111,'Award in Information Technology and Study Skills','certificate',12,'English','Toolkit source: non_exclusive / Malta / row 3.','ELIGIBILITY:\nProspective students who can demonstrate prior appropriate experience may also be admitted.\nProspective students should also be able to demonstrate a suitable level of English language to be able to study and successfully complete this programme.\n\nProspective students should possess at least the appropriate MQF/EQF Level 2 or equivalent qualifications. IELTS Academic (In Centre and Online)  5\n\nREQUIREMENTS / DOCUMENTS:\nAll applicants must have a valid passport (03 months validity from programme end date). \n·       CV required where the study gap is over 3 years (from intake start date). \n·       Academic Transcripts & Certificates. (English translated copies are required if original is in local language). \n·       Affidavit: -  (In case of difference in name on passport and academics).\nGBS Malta\n\nProspective students who can demonstrate prior appropriate experience may also be admitted. Prospective students should also be able to demonstrate a suitable level of English language to be able to study and successfully complete this programme. Prospective students should possess at least the appropriate MQF/EQF Level 2 or equivalent qualifications. IELTS Academic (In Centre and Online) 5\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1748,'01KWJDMFEG9DTB82ME24M3YEVG',111,'Award in Business Management and Study Skills','certificate',12,'English','Toolkit source: non_exclusive / Malta / row 4.','Prospective students who can demonstrate prior appropriate experience may also be admitted. Prospective students should also be able to demonstrate a suitable level of English language to be able to study and successfully complete this programme. Prospective students should possess at least the appropriate MQF/EQF Level 2 or equivalent qualifications. IELTS Academic (In Centre and Online) 5\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1749,'01KWJDMFEKAXZPDCHGEJG8FYFV',111,'BSc (Hons) Health, Social Care and Wellbeing','bachelors',36,'English','Toolkit source: non_exclusive / Malta / row 6.','ELIGIBILITY:\n(a) Possession of certificated qualification(s) at or equivalent to MFHEA MQF Level 4 with at least one qualification in health, social care and/or wellbeing or relevant other.\nPrior learning recognition\nProspective students who have worked in some capacity in an area of health, social care and/or wellbeing and who do not possess formal certificate qualifications at or equivalent to MFHEA MQF Level 4 may have their experiential learning, where appropriate, assessed through GBS Malta\'s MFHEA accredited Policy and Procedure for the Recognition of Prior Learning: Accreditation of Experiential Learning. IELTS Academic (in centre and Online)5.5\n\nREQUIREMENTS / DOCUMENTS:\nAll applicants must have a valid passport (03 months validity from programme end date). \n·       CV required where the study gap is over 3 years (from intake start date). \n·       Academic Transcripts & Certificates. (English translated copies are required if original is in local language). \n·       Affidavit: -  (In case of difference in name on passport and academics).\nBath Spa University\n\n(a) Possession of certificated qualification(s) at or equivalent to MFHEA MQF Level 4 with at least one qualification in health, social care and/or wellbeing or relevant other. Prior learning recognition Prospective students who have worked in some capacity in an area of health, social care and/or wellbeing and who do not possess formal certificate qualifications at or equivalent to MFHEA MQF Level 4 may have their experiential learning, where appropriate, assessed through GBS Malta’s MFHEA accredited Policy and Procedure for the Recognition of Prior Learning: Accreditation of Experiential Learning. IELTS Academic (in centre and Online)5.5\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1750,'01KWJDMFEPE8G1692J2VJZ9QPB',111,'BSc (Hons) Computer Science and Information Technology','bachelors',36,'English','Toolkit source: non_exclusive / Malta / row 7.','ELIGIBILITY:\nAll applicants to the BSc (Hons) Computer Science and Information Technology programme will be required to attend an admissions interview. This may take place at the GBS Malta campus or via virtual platforms.\nTo be considered for a place on this programme, applicants are expected to meet the following admissions criteria: possession of a qualification at, or equivalent to, MFHEA MQF Level 4, with at least one subject in computing, information technology, or a related field. IELTS Academic (in centre and Online)	6\n\nAll applicants to the BSc (Hons) Computer Science and Information Technology programme will be required to attend an admissions interview. This may take place at the GBS Malta campus or via virtual platforms. To be considered for a place on this programme, applicants are expected to meet the following admissions criteria: possession of a qualification at, or equivalent to, MFHEA MQF Level 4, with at least one subject in computing, information technology, or a related field. IELTS Academic (in centre and Online) 6\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1751,'01KWJDMFEQ1QMGSCPY1TWW50Y7',111,'BSc (Hons) Business Management','bachelors',36,'English','Toolkit source: non_exclusive / Malta / row 8.','ELIGIBILITY:\n(a) Possession of certificated qualification(s) at or equivalent to MFHEA MQF Level 4 with at least one qualification in business management or related area.\n(b) Applicants with an MQF Level 4 qualification or equivalent not in business management or related area would be accepted if have relevant related work experience or having undertaken a short bridging course in business management or related area. IELTS Academic (in centre and Online)	5.5\n\n(a) Possession of certificated qualification(s) at or equivalent to MFHEA MQF Level 4 with at least one qualification in business management or related area. (b) Applicants with an MQF Level 4 qualification or equivalent not in business management or related area would be accepted if have relevant related work experience or having undertaken a short bridging course in business management or related area. IELTS Academic (in centre and Online) 5.5\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1752,'01KWJDMFER6SA3M5P05061YE0N',111,'Master of Public Health (Specialization - Epidemiology, Health Promotion and Leadership and Management )','masters',12,'English','Toolkit source: non_exclusive / Malta / row 10.','ELIGIBILITY:\nProspective students who possess the equivalent of a relevant, good honours degree - normally equivalent to a 2:2 or above. (a) Also, health care professionals with an undergraduate honours degree (nurses, social workers, social carers, etc.) would also be appropriate. \n(b) Possess the equivalent of a relevant UK or other recognised degree (as specified in (a) above) below a 2:2 standard whilst being able to evidence aptitude and/or relevant work/management experience in a health-related area to successfully complete the MPH programme of study. \n(c) Possess an appropriate professional body qualification, for example, nursing, social work, social care, physiotherapy, occupational therapy, midwifery . IELTS Academic (in centre and Online)	6\n\nREQUIREMENTS / DOCUMENTS:\nAll applicants must have a valid passport (03 months validity from programme end date). \n·       CV required where the study gap is over 3 years (from intake start date). \n·       Academic Transcripts & Certificates. (English translated copies are required if original is in local language). \n·       Affidavit: -  (In case of difference in name on passport and academics).\nGBS Malta\n\nProspective students who possess the equivalent of a relevant, good honours degree – normally equivalent to a 2:2 or above. (a) Also, health care professionals with an undergraduate honours degree (nurses, social workers, social carers, etc.) would also be appropriate. (b) Possess the equivalent of a relevant UK or other recognised degree (as specified in (a) above) below a 2:2 standard whilst being able to evidence aptitude and/or relevant work/management experience in a health-related area to successfully complete the MPH programme of study. (c) Possess an appropriate professional body qualification, for example, nursing, social work, social care, physiotherapy, occupational therapy, midwifery . IELTS Academic (in centre and Online) 6\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1753,'01KWJDMFES04V57ANHKRDQE82P',111,'MSc Information Technology Management (Specialization - Cybersecurity, Data analytics, Cloud Computing & Artificial Intelligence','masters',12,'English','Toolkit source: non_exclusive / Malta / row 11.','ELIGIBILITY:\nPossess the equivalent (MQF Level 6) of a relevant, good honours degree from a UK university - normally equivalent to a 2:2 or higher. A range of subjects studied at undergraduate degree level would be considered. Examples include degree in computing or IT, business and management studies involving some IT components, engineering and information management. Prospective students would be required to demonstrate a committment to studying Information Technology Management at the Master\'s level.  \nPossess the equivalent (MQF Level 6) of a relevant UK degree below a 2:2 standard whilst being able to evidence an aptitude and/or relevant work/management experience to successfully complete the Master of Science in Information Technology Management programme of study. IELTS Academic (in centre and Online)	6\n\nPossess the equivalent (MQF Level 6) of a relevant, good honours degree from a UK university – normally equivalent to a 2:2 or higher. A range of subjects studied at undergraduate degree level would be considered. Examples include degree in computing or IT, business and management studies involving some IT components, engineering and information management. Prospective students would be required to demonstrate a committment to studying Information Technology Management at the Master’s level. Possess the equivalent (MQF Level 6) of a relevant UK degree below a 2:2 standard whilst being able to evidence an aptitude and/or relevant work/management experience to successfully complete the Master of Science in Information Technology Management programme of study. IELTS Academic (in centre and Online) 6\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1754,'01KWJDMFEW4GAP6YAS9WNPCDJP',111,'Master of Business Administration (Specialization - Marketing Management, Management Consulting, Project Management, Entrepreneurship and Global Investment Banking','masters',12,'English','Toolkit source: non_exclusive / Malta / row 12.','ELIGIBILITY:\nPossess the equivalent of a good UK honours degree - normally equivalent to a 2:2 or above.\nPossess the equivalent of a UK degree below a 2:2 standard whilst being able to evidence an aptitude and/or relevant work/management experience to successfully complete the MBA programme of study.\nPossess appropriate professional body qualifications (for example, ACCA or CIMA) at a level equivalent to UK undergraduate degree. IELTS Academic (in centre and Online) 6\n\nPossess the equivalent of a good UK honours degree – normally equivalent to a 2:2 or above. Possess the equivalent of a UK degree below a 2:2 standard whilst being able to evidence an aptitude and/or relevant work/management experience to successfully complete the MBA programme of study. Possess appropriate professional body qualifications (for example, ACCA or CIMA) at a level equivalent to UK undergraduate degree. IELTS Academic (in centre and Online) 6\n\nAll applicants must have a valid passport (03 months validity from programme end date). · CV required where the study gap is over 3 years (from intake start date). · Academic Transcripts & Certificates. (English translated copies are required if original is in local language). · Affidavit: - (In case of difference in name on passport and academics).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
