INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1821,'01KWJDMFG8QPE1SHEM54GDVV9D',115,'BSc in Aviation Maintenance Engineering & Management','bachelors',NULL,'English','Toolkit source: non_exclusive / Malta / row 91.','ELIGIBILITY:\nFor non-native English speakers, an overall IELTS score of at least 6.0 or a TOEFL iBT score of at least 80 is required.\n\nREQUIREMENTS / DOCUMENTS:\nCompletion of secondary education (12 years of formal education), with a recognized secondary school leaving certificate or a high school diploma.\n\nFor students following the US system, a GPA of 2.0 or higher is required.\n\nFor students following the British system, five subject exams with grades of D or above on each.\n\nAUM accepts comparable international qualifications.                                                                                                       Application Documents:\n\nOfficial transcripts from all prior institutions.\n\nProof of English proficiency.\n\nA passport or other valid form of identification.\n\nFor non-native English speakers, an overall IELTS score of at least 6.0 or a TOEFL iBT score of at least 80 is required.\n\nCompletion of secondary education (12 years of formal education), with a recognized secondary school leaving certificate or a high school diploma. For students following the US system, a GPA of 2.0 or higher is required. For students following the British system, five subject exams with grades of D or above on each. AUM accepts comparable international qualifications. Application Documents: Official transcripts from all prior institutions. Proof of English proficiency. A passport or other valid form of identification.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
