INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1832,'01KWJDMFGE032H5ETBK7XKQBVG',115,'Master of Business Administration','masters',NULL,'English','Toolkit source: non_exclusive / Malta / row 103.','ELIGIBILITY:\nFor non-native English speakers, an overall IELTS score of at least 6.5 or a TOEFL iBT score of at least 79 is required.\n\nREQUIREMENTS / DOCUMENTS:\nA relevant bachelor\'s degree (EQF/MQF Level 6) with a minimum of 180/240 ECTS.\n\nA Cumulative Grade Point Average (CGPA) of at least 2.2.                                                                                           Official transcripts and certified English translations if necessary.\n\nA personal statement or statement of purpose.\n\nLetters of recommendation.\n\nProof of English proficiency.\n\nFor non-native English speakers, an overall IELTS score of at least 6.5 or a TOEFL iBT score of at least 79 is required.\n\nA relevant bachelor\'s degree (EQF/MQF Level 6) with a minimum of 180/240 ECTS. A Cumulative Grade Point Average (CGPA) of at least 2.2. Official transcripts and certified English translations if necessary. A personal statement or statement of purpose. Letters of recommendation. Proof of English proficiency.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
