INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1899,'01KWJDMFHXBQ8CNEZNJKF3F8CP',120,'Master of Business Administration (MBA)','masters',24,'English','Toolkit source: non_exclusive / Malta / row 206.','ELIGIBILITY:\n1. Bachelor\'s degree: Students need to hold a bachelor\'s degree at MQF level 6 or an equivalent qualification. \nOR\n2. Age and Managerial Experience: If a student does not have a bachelor\'s degree but holds other qualifications, they must be at least 25 years of age and over, and have a minimum of 5 years of managerial experience proved by written evidence. This experience should demonstrate a level of responsibility and leadership that is equivalent to that gained from completing an undergraduate degree. ans IELTS 6.5 & equivalent\n\nREQUIREMENTS / DOCUMENTS:\nDocuments Required:- Certificates and Transcripts; Curriculum Vitae (CV); Letters of Recommendation; Moticational Letter, Valid Passport Copy; Passport Size Photographs and Englis Proficiency\n\n1. Bachelor\'s degree: Students need to hold a bachelor\'s degree at MQF level 6 or an equivalent qualification. OR 2. Age and Managerial Experience: If a student does not have a bachelor\'s degree but holds other qualifications, they must be at least 25 years of age and over, and have a minimum of 5 years of managerial experience proved by written evidence. This experience should demonstrate a level of responsibility and leadership that is equivalent to that gained from completing an undergraduate degree. ans IELTS 6.5 & equivalent\n\nDocuments Required:- Certificates and Transcripts; Curriculum Vitae (CV); Letters of Recommendation; Moticational Letter, Valid Passport Copy; Passport Size Photographs and Englis Proficiency','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:37',NULL);
