INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1931,'01KWJDMFJN3ETCBAXEK9816NKH',122,'Baltic Film, Media and Arts School','bachelors',36,'English','Toolkit source: non_exclusive / Estonia / row 13.','ELIGIBILITY:\nAt least 60% of maximum possible results is expected in order to qualify for studies at Tallinn University.                                                  IELTS - 6.0 (with a minimum of 5.5 in each component)\n\nREQUIREMENTS / DOCUMENTS:\nThe access requirement to Bachelor\'s studies is secondary education or a corresponding qualification.\nThe following documents must be uploaded to the online application system:\nHigher Secondary School Certificate issued by Examination Board or a corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education\nMarks Statement\n\nAt least 60% of maximum possible results is expected in order to qualify for studies at Tallinn University. IELTS - 6.0 (with a minimum of 5.5 in each component)\n\nThe access requirement to Bachelor\'s studies is secondary education or a corresponding qualification. The following documents must be uploaded to the online application system: Higher Secondary School Certificate issued by Examination Board or a corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education Marks Statement','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:38',NULL);
