INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1933,'01KWJDMFJPZ3JSCJ680K6BFHPX',122,'School of Humanities','bachelors',36,'English',NULL,'ELIGIBILITY:\nPlease note: A First Division/Class or First Division/Class with Distinction (at least 60% of maximum possible results) degree is required in order to qualify for Master\'s studies at Tallinn University.                                       IELTS - 6.0 (with a minimum of 5.5 in each component)\n\nREQUIREMENTS / DOCUMENTS:\nThe access requirement to Master\'s studies is a Bachelor\'s degree, a diploma of professional higher education or a corresponding qualification.\n\nThe following documents* must be uploaded to the online application system:\n\nBachelor\'s degree certificate or a provisional certificate**\nBachelor\'s degree transcript of records***\n* If your studies include transferred credits from other institutions, transcripts from these must also be uploaded.\n\n** The Bachelor\'s degree certificate or the provisional certificate must be awarded by the university and not the college.\n\n*** The transcript of records may be awarded by the college.\nAfter receiving conditional acceptance, the applicant\'s official academic transcript must be sent to Tallinn University\'s postal address by the institution that awarded the degree upon the request of the applicant. Academic transcripts sent by the applicant will not be accepted.','active',NULL,'2026-07-03 03:31:50','2026-07-03 03:31:50',NULL);
