INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1938,'01KWJDMFJSKP8Z89B3G6JBGAZX',123,'The Business Administration bachelor\'s','bachelors',36,'English','Toolkit source: non_exclusive / Estonia / row 32.','ELIGIBILITY:\nApplications are evaluated based on\n\nthe score of the motivation letter (yields 60% of the final score)\nonline entry test in Mathematics (yields 40% of the final score)                       The University of Tartu has specific English language requirements for admission, with different deadlines for Bachelor\'s and Master\'s programs.\n\nAccepted English Proficiency Tests and Minimum Scores:\nTOEFL iBT: A minimum score of 75 is required. The university accepts the TOEFL iBT, Home Edition, and Paper Edition.\n\nIELTS Academic: A minimum overall score of 6.0 is required, with no section scoring lower than 5.5. General Training IELTS is not accepted.\n\nCambridge English Tests: A minimum score of 169 is required for the B2 First (FCE), C1 Advanced (CAE), and C2 Proficiency (CPE) tests.\n\nPearson Test of English Academic (PTE Academic): A minimum score of 59 is required for both the standard and online versions.\n\nREQUIREMENTS / DOCUMENTS:\nTo apply for bachelor\'s studies secondary education or a corresponding qualification is required.\n\nThe following education documents must be uploaded to the online application system:\n\nHigher Secondary School Certificate issued by Examination Board or a corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education\n\nMarks Statement\n\nNB! Course grades lower than 50% are considered a negative result in Estonia. Applicants with more than 10% of the final course grades lower than 50% do not qualify for university studies in Estonia.\n\nApplications are evaluated based on the score of the motivation letter (yields 60% of the final score) online entry test in Mathematics (yields 40% of the final score) The University of Tartu has specific English language requirements for admission, with different deadlines for Bachelor\'s and Master\'s programs. Accepted English Proficiency Tests and Minimum Scores: TOEFL iBT: A minimum score of 75 is required. The university accepts the TOEFL iBT, Home Edition, and Paper Edition. IELTS Academic: A minimum overall score of 6.0 is required, with no section scoring lower than 5.5. General Training IELTS is not accepted. Cambridge English Tests: A minimum score of 169 is required for the B2 First (FCE), C1 Advanced (CAE), and C2 Proficiency (CPE) tests. Pearson Test of English Academic (PTE Academic): A minimum score of 59 is required for both the standard and online versions.\n\nTo apply for bachelor\'s studies secondary education or a corresponding qualification is required. The following education documents must be uploaded to the online application system: Higher Secondary School Certificate issued by Examination Board or a corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education Marks Statement NB! Course grades lower than 50% are considered a negative result in Estonia. Applicants with more than 10% of the final course grades lower than 50% do not qualify for university studies in Estonia.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:38',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1939,'01KWJDMFJTFZEVD2W8D944GX4W',123,'Science and Technology','bachelors',36,'English','Toolkit source: non_exclusive / Estonia / row 33.','Applications are evaluated based on the score of the motivation letter (yields 60% of the final score) online entry test in Mathematics (yields 40% of the final score) The University of Tartu has specific English language requirements for admission, with different deadlines for Bachelor\'s and Master\'s programs. Accepted English Proficiency Tests and Minimum Scores: TOEFL iBT: A minimum score of 75 is required. The university accepts the TOEFL iBT, Home Edition, and Paper Edition. IELTS Academic: A minimum overall score of 6.0 is required, with no section scoring lower than 5.5. General Training IELTS is not accepted. Cambridge English Tests: A minimum score of 169 is required for the B2 First (FCE), C1 Advanced (CAE), and C2 Proficiency (CPE) tests. Pearson Test of English Academic (PTE Academic): A minimum score of 59 is required for both the standard and online versions.\n\nTo apply for bachelor\'s studies secondary education or a corresponding qualification is required. The following education documents must be uploaded to the online application system: Higher Secondary School Certificate issued by Examination Board or a corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education Marks Statement NB! Course grades lower than 50% are considered a negative result in Estonia. Applicants with more than 10% of the final course grades lower than 50% do not qualify for university studies in Estonia.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:38',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1940,'01KWJDMFJTFZEVD2W8D944GX4Y',123,'Actuarial and Financial Engineering','masters',24,'English','Toolkit source: non_exclusive / Estonia / row 35.','ELIGIBILITY:\nbachelor\'s degree or equivalent qualification (must be obtained by the end of July) - please see our country-specific document requirements\nprerequisite courses: at least 24 ECTS completed in the previous level of studies in mathematics, incl. calculus, probability, statistics and 6 ECTS completed in computer science\nEnglish language proficiency - please see our acceptable tests and exempt categories.                                                              average grade of the previous study level (yields 40% of the final score)\nthe score of the motivation letter (yields 30% of the final score)\ninterview (yields 30% of the final score)                                                The University of Tartu has specific English language requirements for admission, with different deadlines for Bachelor\'s and Master\'s programs.\n\nAccepted English Proficiency Tests and Minimum Scores:\nTOEFL iBT: A minimum score of 75 is required. The university accepts the TOEFL iBT, Home Edition, and Paper Edition.\n\nIELTS Academic: A minimum overall score of 6.0 is required, with no section scoring lower than 5.5. General Training IELTS is not accepted.\n\nCambridge English Tests: A minimum score of 169 is required for the B2 First (FCE), C1 Advanced (CAE), and C2 Proficiency (CPE) tests.\n\nPearson Test of English Academic (PTE Academic): A minimum score of 59 is required for both the standard and online versions.\n\nREQUIREMENTS / DOCUMENTS:\nTo apply for master\'s studies a bachelor\'s degree, a diploma of professional higher education or a corresponding qualification is required.\n\nThe following education documents must be uploaded to the online application system:\n\nBachelor\'s degree certificate or Provisional Certificate\nThe Bachelor\'s degree certificate or Provisional Certificate must be awarded by the University and not the College.\n\nTranscript of records\nThe Transcript of Records may be awarded by the College.\n\nbachelor’s degree or equivalent qualification (must be obtained by the end of July) – please see our country-specific document requirements prerequisite courses: at least 24 ECTS completed in the previous level of studies in mathematics, incl. calculus, probability, statistics and 6 ECTS completed in computer science English language proficiency – please see our acceptable tests and exempt categories. average grade of the previous study level (yields 40% of the final score) the score of the motivation letter (yields 30% of the final score) interview (yields 30% of the final score) The University of Tartu has specific English language requirements for admission, with different deadlines for Bachelor\'s and Master\'s programs. Accepted English Proficiency Tests and Minimum Scores: TOEFL iBT: A minimum score of 75 is required. The university accepts the TOEFL iBT, Home Edition, and Paper Edition. IELTS Academic: A minimum overall score of 6.0 is required, with no section scoring lower than 5.5. General Training IELTS is not accepted. Cambridge English Tests: A minimum score of 169 is required for the B2 First (FCE), C1 Advanced (CAE), and C2 Proficiency (CPE) tests. Pearson Test of English Academic (PTE Academic): A minimum score of 59 is required for both the standard and online versions.\n\nTo apply for master’s studies a bachelor’s degree, a diploma of professional higher education or a corresponding qualification is required. The following education documents must be uploaded to the online application system: Bachelor’s degree certificate or Provisional Certificate The Bachelor’s degree certificate or Provisional Certificate must be awarded by the University and not the College. Transcript of records The Transcript of Records may be awarded by the College.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:38',NULL);
