INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1976,'01KWJDMFKBJ3M7ANPZXJE8ZC1J',126,'School of Information Technologies','bachelors',NULL,'English',NULL,'ELIGIBILITY:\nIELTS Academic: A minimum overall score of 6.0, with no band lower than 5.5.\n\nTOEFL iBT: A minimum total score of 75.\n\nCambridge English: A minimum overall score of 165, with no component lower than 160.\n\nPearson Test of English Academic (PTE Academic): A minimum overall score of 59, with no communicative skill component lower than 59.\n\nREQUIREMENTS / DOCUMENTS:\nNOTE! In order to qualify for the studies in Tallinn University of Technology an applicant has to have at least 60% of the highest possible CGPA (Cumulative Grade Point Average, total score).\n\nIn the online application system, the following education documents must be uploaded:\n\n➤ When applying for a Bachelor\'s programme:\n\nHigher Secondary School Certificate issued by Examination Board/ Corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education\nAcademic transcript/ Statement of marks/ Mark sheet\nNote: In Estonia a course grade less than 50% is considered a negative result and does not grant access to higher education. Therefore higher secondary school transcripts with more than 10% negative results (under 50%) are not accepted','active',NULL,'2026-07-03 03:31:50','2026-07-03 03:31:50',NULL);
