INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1982,'01KWJDMFKFXK2FEQZMRE3JF81R',126,'BSc Integrated Engineering','bachelors',36,'English','Toolkit source: non_exclusive / Estonia / row 84.','IELTS Academic: A minimum overall score of 6.0, with no band lower than 5.5. TOEFL iBT: A minimum total score of 75. Cambridge English: A minimum overall score of 165, with no component lower than 160. Pearson Test of English Academic (PTE Academic): A minimum overall score of 59, with no communicative skill component lower than 59.\n\nNOTE! In order to qualify for the studies in Tallinn University of Technology an applicant has to have at least 60% of the highest possible CGPA (Cumulative Grade Point Average, total score). In the online application system, the following education documents must be uploaded: ➤ When applying for a Bachelor\'s programme: Higher Secondary School Certificate issued by Examination Board/ Corresponding 10+2 certificate awarded upon completion of higher or intermediate secondary education Academic transcript/ Statement of marks/ Mark sheet Note: In Estonia a course grade less than 50% is considered a negative result and does not grant access to higher education. Therefore higher secondary school transcripts with more than 10% negative results (under 50%) are not accepted','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:38',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (1983,'01KWJDMFKFXK2FEQZMRE3JF81V',126,'School of Information Technologies','masters',36,'English',NULL,'ELIGIBILITY:\n\"IELTS Academic: A minimum overall score of 6.0, with no band lower than 5.5.\n\nTOEFL iBT: A minimum total score of 75.\n\nCambridge English: A minimum overall score of 165, with no component lower than 160.\n\nPearson Test of English Academic (PTE Academic): A minimum overall score of 59, with no communicative skill component lower than 59.\"\n\nREQUIREMENTS / DOCUMENTS:\n➤ When applying for a Master\'s programme:\n\nBachelor\'s degree diploma or Provisional Certificate\nBachelor\'s degree academic transcript\nNote: College-issued diplomas/provisional certificates will not be accepted. Diploma must be issued by the Registrar\'s Office or the Controller or Examinations Office at the university.','active',NULL,'2026-07-03 03:31:50','2026-07-03 03:31:50',NULL);
