INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2062,'01KWJDMFQRH3E89Q9Z6P77YWVB',129,'Business Administration','bachelors',48,'English','Toolkit source: non_exclusive / Latvia / row 47.','ELIGIBILITY:\nEducation Certificates:\nSenior secondary certificate (for bachelor\'s)\nBachelor\'s degree certificate with transcript (for master\'s)\nMaster\'s degree certificate with transcript (for doctoral)\nAll documents must be in original language + official English translation\nEnglish Proficiency Certificate (if available):\nIf not available, the applicant must take Turība\'s online English test\nCurriculum Vitae (CV)\nPassport Copy\nPassport-size Photograph\nUpload all documents during online application + send notarized copies by courier/mail to Turība University\n\nApplication Fee:\nEUR 200 (non-refundable)\nOnline Entrance Tests + Interview:\nMandatory for all applicants\n\nREQUIREMENTS / DOCUMENTS:\nCompleted senior secondary education with a transcript\n\nMust pass online entrance tests:\n\nMath test (for Computer Systems programme)\n\nSocial Science test (for other programmes)\n\nMust prove English proficiency or take Turība\'s online English test\n\nEducation Certificates: Senior secondary certificate (for bachelor’s) Bachelor’s degree certificate with transcript (for master’s) Master’s degree certificate with transcript (for doctoral) All documents must be in original language + official English translation English Proficiency Certificate (if available): If not available, the applicant must take Turība\'s online English test Curriculum Vitae (CV) Passport Copy Passport-size Photograph Upload all documents during online application + send notarized copies by courier/mail to Turība University Application Fee: EUR 200 (non-refundable) Online Entrance Tests + Interview: Mandatory for all applicants\n\nCompleted senior secondary education with a transcript Must pass online entrance tests: Math test (for Computer Systems programme) Social Science test (for other programmes) Must prove English proficiency or take Turība\'s online English test','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:39',NULL);
