INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2198,'01KWJDMFT4DQ3Y85QX9A31R82K',134,'Bachelor\'s Degree Programmes','bachelors',NULL,'English','Toolkit source: non_exclusive / Latvia / row 192.','ELIGIBILITY:\n1. IELTS Academic\nMinimum Required Score: 5.5 or Level B2\nAdditional Requirements: Every part should be at least 5.5\nValidity: Two years\n\n2. TOEFL iBT\nMinimum Required Score: 75\nAdditional Requirements: Every part should be at least 18 points\nValidity: Two years\n\n3. TOEFL PBT\nMinimum Required Score: 540\nAdditional Requirements: None\nValidity: Two years\n\n4. TOEFL CBT\nMinimum Required Score: 205\nAdditional Requirements: None\nValidity: Two years\n\n5. Cambridge First Certificate in English (FCE)\nMinimum Required Score: 160\nAdditional Requirements: None\nValidity: No expiry date (accepted if received within the last 3 years)\n\n6. Cambridge Certificate in Advanced English (CAE)\nMinimum Required Score: Not specified\nAdditional Requirements: None\nValidity: No expiry date (accepted if received within the last 3 years)\n\n7. Cambridge Certificate of Proficiency in English (CPE)\nMinimum Required Score: Not specified\nAdditional Requirements: None\nValidity: No expiry date (accepted if received within the last 3 years)\n\n8. ECL\nMinimum Required Score: Level B2\nAdditional Requirements: None\nValidity: No expiry date (accepted if received within the last 3 years)\n\n9. Duolingo\nMinimum Required Score: 100\nAdditional Requirements: None\nValidity: Two years\n\nREQUIREMENTS / DOCUMENTS:\nCopy of Passport;\nDocuments of student\'s previous education:  the Secondary school certificates/transcripts/the list of exams; the Recognized University diploma/certificates/transcripts - for Master\'s Degree  Programmes;\nInternational English proficiency certificate Upper-Intermediate B2 (5.5 with 5.5 or above in each band) - for more detailed information press here.  \n4 photos (35 x 45 mm);\nCurriculum Vitae and Motivation letter - for Master\'s Degree  programmes; work reference letters (if available) - for Master\'s Degree  programmes.\nInitiation of studies in subsequent study stages:\n\nPersons who have higher education or who have studied in higher education institutions until now  additionally submit the following documents:\n• a copy of the diploma and its Annex and/or a copy of the transcript of records on the basis of which credits obtained in the institution of higher education are credited;\n• Report/exam transfer form (original).\n\n1. IELTS Academic Minimum Required Score: 5.5 or Level B2 Additional Requirements: Every part should be at least 5.5 Validity: Two years 2. TOEFL iBT Minimum Required Score: 75 Additional Requirements: Every part should be at least 18 points Validity: Two years 3. TOEFL PBT Minimum Required Score: 540 Additional Requirements: None Validity: Two years 4. TOEFL CBT Minimum Required Score: 205 Additional Requirements: None Validity: Two years 5. Cambridge First Certificate in English (FCE) Minimum Required Score: 160 Additional Requirements: None Validity: No expiry date (accepted if received within the last 3 years) 6. Cambridge Certificate in Advanced English (CAE) Minimum Required Score: Not specified Additional Requirements: None Validity: No expiry date (accepted if received within the last 3 years) 7. Cambridge Certificate of Proficiency in English (CPE) Minimum Required Score: Not specified Additional Requirements: None Validity: No expiry date (accepted if received within the last 3 years) 8. ECL Minimum Required Score: Level B2 Additional Requirements: None Validity: No expiry date (accepted if received within the last 3 years) 9. Duolingo Minimum Required Score: 100 Additional Requirements: None Validity: Two years\n\nCopy of Passport; Documents of student\'s previous education: the Secondary school certificates/transcripts/the list of exams; the Recognized University diploma/certificates/transcripts – for Master\'s Degree Programmes; International English proficiency certificate Upper-Intermediate B2 (5.5 with 5.5 or above in each band) - for more detailed information press here. 4 photos (35 x 45 mm); Curriculum Vitae and Motivation letter – for Master\'s Degree programmes; work reference letters (if available) – for Master\'s Degree programmes. Initiation of studies in subsequent study stages: Persons who have higher education or who have studied in higher education institutions until now additionally submit the following documents: • a copy of the diploma and its Annex and/or a copy of the transcript of records on the basis of which credits obtained in the institution of higher education are credited; • Report/exam transfer form (original).','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:40',NULL);
