INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2218,'01KWJDMFTTPT5E8Q3C9BKGEKN2',136,'Information systems','bachelors',48,'English','Toolkit source: non_exclusive / Latvia / row 217.','The foreign applicants who choose to study in the English language shall submit a document issued by an international testing institution certifying his/her knowledge of English. The document must be issued no earlier than five previous years. Language skills shall be not lower than B2 level according to ECP. The foreign applicants who acquired secondary education in English do not have to submit the documents certifying their knowledge of the study programme language.\n\nStandard application form; Passport copy; Foreign passport; 2 photographs (3x4 size); A copy of the full secondary education with grades*; A copy of the bachelor`s / professional / master degree and diploma supplement with grades (if any);** The foreign applicants who choose to study in the English language shall submit a document issued by an international testing institution certifying his/her knowledge of English. The document must be issued no earlier than five previous years. Language skills shall be not lower than B2 level according to ECP. The foreign applicants who acquired secondary education in English do not have to submit the documents certifying their knowledge of the study programme language.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:40',NULL);
