INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2429,'01KWJDMFZ0WM4NQG21T32KQ33W',140,'Economics and Politics',NULL,42,'English','Language requirement: ISM English test (minimum score of 55);\nTOEFL (minimum score of IBT 60 points);\nIELTS (minimum score of 6);\nCambridge English test Level B2 Certificate (minimum score of 169);\nPTE Academic (minimum score of 52);\nDuolingo English Test (minimum score of 115);\nInternational Baccalaureate or European Baccalaureate diploma;\nEnglish state exam result is equal or higher than Level B2 if applicant is from Estonia or Latvia;\n*Applicants whose previous education was taught entirely in English may also be exempted from the English language requirement, subject to the decision of the admissions committee.\n\nToolkit source: non_exclusive / Lithuania / row 211.','ELIGIBILITY:\nA secondary school education completed or if you are in your final year at school you need to submit transcript grades;\nState mathematics examination or, if the person has not taken this exam, the ISM mathematics test results.\n\nA secondary school education completed or if you are in your final year at school you need to submit transcript grades; State mathematics examination or, if the person has not taken this exam, the ISM mathematics test results.\n\nISM English test (minimum score of 55); TOEFL (minimum score of IBT 60 points); IELTS (minimum score of 6); Cambridge English test Level B2 Certificate (minimum score of 169); PTE Academic (minimum score of 52); Duolingo English Test (minimum score of 115); International Baccalaureate or €pean Baccalaureate diploma; English state exam result is equal or higher than Level B2 if applicant is from Estonia or Latvia; *Applicants whose previous education was taught entirely in English may also be exempted from the English language requirement, subject to the decision of the admissions committee.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:37:02',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2430,'01KWJDMFZ15PR989WK44C7V6X9',140,'Economics and Data Analytics',NULL,42,'English','Toolkit source: non_exclusive / Lithuania / row 212.','A secondary school education completed or if you are in your final year at school you need to submit transcript grades; State mathematics examination or, if the person has not taken this exam, the ISM mathematics test results.\n\nISM English test (minimum score of 55); TOEFL (minimum score of IBT 60 points); IELTS (minimum score of 6); Cambridge English test Level B2 Certificate (minimum score of 169); PTE Academic (minimum score of 52); Duolingo English Test (minimum score of 115); International Baccalaureate or €pean Baccalaureate diploma; English state exam result is equal or higher than Level B2 if applicant is from Estonia or Latvia; *Applicants whose previous education was taught entirely in English may also be exempted from the English language requirement, subject to the decision of the admissions committee.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:37:02',NULL);
