INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2446,'01KWJDMFZE2DVY77F9D3CZEPMR',142,'Program',NULL,NULL,'English',NULL,'ELIGIBILITY:\nAcademic Qualifications\nHigh School Diploma: Completion of Grade 12 or equivalent (e.g., A-Level, IB Diploma).\n\nSpecific Major Requirements:\nComputer Science: High School Science stream or Vocational High School (SMK) in Technology, Computing, or Design.\nOther Majors: Open to all high school majors\n\nREQUIREMENTS / DOCUMENTS:\nRequired Documents\nCompleted application form.\nTranscripts from Grades 10-12.\nHigh school diploma or national exam certificate.\nEnglish proficiency test scores (TOEFL, IELTS, or equivalent).\nColor copy of passport (valid for the duration of study).\nPassport-sized photograph (4×6 cm, max 300 KB).\nCurriculum Vitae (CV).\nMotivation letter.\nProof of financial competency (e.g., bank statement).\nBirth certificate\n\nEntrance Tests\nBINUS International Aptitude Test: Logic, abstraction, and verbal reasoning.\nEnglish Proficiency Test: BINUS International English Proficiency Test (BIEPT).\nTest of Written English (TWE).\nDrawing Test: Required for applicants to Graphic Design & New Media.\n\nEnglish Language Requirements\nStandard Admission:\nTOEFL PBT: 550\nTOEFL iBT: 80\nIELTS: 6.0\n\nScholarship Applicants:\nMinimum IELTS score of 6.5 or equivalent.\n\nConditional Admission:\nApplicants with lower scores may be required to complete a 150-hour pre-sessional English course.','active',NULL,'2026-07-03 03:31:50','2026-07-03 03:31:50',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2447,'01KWJDMFZF5541MQHXCD2WQ68B',142,'Business Information Systems',NULL,NULL,'English','Toolkit source: non_exclusive / Indonesia / row 3.','Academic Qualifications High School Diploma: Completion of Grade 12 or equivalent (e.g., A-Level, IB Diploma). Specific Major Requirements: Computer Science: High School Science stream or Vocational High School (SMK) in Technology, Computing, or Design. Other Majors: Open to all high school majors\n\nRequired Documents Completed application form. Transcripts from Grades 10–12. High school diploma or national exam certificate. English proficiency test scores (TOEFL, IELTS, or equivalent). Color copy of passport (valid for the duration of study). Passport-sized photograph (4×6 cm, max 300 KB). Curriculum Vitae (CV). Motivation letter. Proof of financial competency (e.g., bank statement). Birth certificate Entrance Tests BINUS International Aptitude Test: Logic, abstraction, and verbal reasoning. English Proficiency Test: BINUS International English Proficiency Test (BIEPT). Test of Written English (TWE). Drawing Test: Required for applicants to Graphic Design & New Media. English Language Requirements Standard Admission: TOEFL PBT: 550 TOEFL iBT: 80 IELTS: 6.0 Scholarship Applicants: Minimum IELTS score of 6.5 or equivalent. Conditional Admission: Applicants with lower scores may be required to complete a 150-hour pre-sessional English course.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:44:33',NULL);
