INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2504,'01KWJDMG0D13XPNV8AYH6Z1M8N',145,'BSc - Animation','bachelors',36,'English','Toolkit source: non_exclusive / UAE / row 43.','REQUIREMENTS / DOCUMENTS:\nCandidates should have completed the 10+2 examination or its equivalent from a recognised educational board ; Candidates must have achieved a minimum of 45% in aggregate marks in their qualifying examination ; Language Proficiency: Minimum 60% in English in the qualifying exam (12th for UG). If not met, clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with overall 5\n\nCandidates must have passed the 10+2 examination or its equivalent with a minimum of 50% aggregate marks. Proficiency in English is also required.\n\nCandidates should have completed the 10+2 examination or its equivalent from a recognised educational board ; Candidates must have achieved a minimum of 45% in aggregate marks in their qualifying examination ; Language Proficiency: Minimum 60% in English in the qualifying exam (12th for UG). If not met, clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with overall 5','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:41',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2505,'01KWJDMG0D13XPNV8AYH6Z1M8Q',145,'Bachelor of Architecture (BArch)','bachelors',60,'English','Toolkit source: non_exclusive / UAE / row 44.','REQUIREMENTS / DOCUMENTS:\n1. Mandatory pass in the 10+2 or equivalent examination, with Physics and Mathematics as compulsory subjects, along with any one of the following:\nChemistry, Biology, Technical Vocational Subject, Computer Science, Information Technology, Informatics Practices, Engineering Graphics, or Business Studies, securing a minimum of 45% marks in aggregate.                                2.  Alternatively, mandatory pass in the 10+3 Diploma Examination, with Mathematics as a compulsory subject, securing at least 45% marks in aggregate..                                                  3. All Candidates must qualify for an aptitude test in architecture conducted by NTA (ie JEE Main Paper II) or by COA (National Aptitude Test in Architecture (NATA) conducted by Council of Architecture (COA)).                                     4. Language Proficiency: Minimum 60% in English in the qualifying exam (12th for UG). If not met, clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with overall 5.\n\nCandidates must have passed the 10+2 examination or its equivalent with a minimum of 50% aggregate marks. Proficiency in English is also required.\n\n1. Mandatory pass in the 10+2 or equivalent examination, with Physics and Mathematics as compulsory subjects, along with any one of the following: Chemistry, Biology, Technical Vocational Subject, Computer Science, Information Technology, Informatics Practices, Engineering Graphics, or Business Studies, securing a minimum of 45% marks in aggregate. 2. Alternatively, mandatory pass in the 10+3 Diploma Examination, with Mathematics as a compulsory subject, securing at least 45% marks in aggregate.. 3. All Candidates must qualify for an aptitude test in architecture conducted by NTA (ie JEE Main Paper II) or by COA (National Aptitude Test in Architecture (NATA) conducted by Council of Architecture (COA)). 4. Language Proficiency: Minimum 60% in English in the qualifying exam (12th for UG). If not met, clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with overall 5.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:41',NULL);
