INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2517,'01KWJDMG0JCZ552WDH1613PG3V',145,'PG Diploma - Cyber Security','bachelors',12,'English','Toolkit source: non_exclusive / UAE / row 56.','REQUIREMENTS / DOCUMENTS:\n1. A bachelor\'s degree from a recognised institute/university with Mathematics, Computing, or IT as part of the curriculum.\nA minimum of 50% aggregate marks in the qualifying degree.                                                     2. Minimum 60% in English in the qualifying exam. If not met, applicants must clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with a minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with an overall score of 6.\nExplore More\n\nMBA in International Business: Applicants must have a Bachelor\'s Degree from a recognized university and must demonstrate proficiency in English. (Source: Master of Business Administration (MBA) Program) MSc in Applied Psychology: Prospective students should have a bachelor\'s degree of a minimum of three years in any discipline with at least 50% aggregate marks from a recognized university. (Source: Master of Science in Applied Psychology) MSc in Medical Biotechnology: Eligibility criteria require students to hold a bachelor\'s degree in any Life Science subject from a recognized university with at least 50% aggregate marks in their undergraduate degree. (Source: Msc in Medical Biotechnology) MSc in Information Science: Candidates should be a graduate with a BSc(IT)/BSc(ISM)/BCA/BSc (Computer Science)/B.Sc./BBA (IT)/B. Tech/B.E from a recognized University or any other graduate with a minimum of three years of experience in the field of IT. (Source: MSc Information Systems)\n\n1. A bachelor’s degree from a recognised institute/university with Mathematics, Computing, or IT as part of the curriculum. A minimum of 50% aggregate marks in the qualifying degree. 2. Minimum 60% in English in the qualifying exam. If not met, applicants must clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with a minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with an overall score of 6. Explore More','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:41',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2518,'01KWJDMG0JCZ552WDH1613PG3X',145,'MBA - Marketing (Day)','bachelors',24,'English','Toolkit source: non_exclusive / UAE / row 57.','REQUIREMENTS / DOCUMENTS:\n1.Applicants must hold a Bachelor\'s Degree from a recognised university, making the program accessible to fresh graduates, working executives, and self-employed professionals.                    2. Minimum 60% in English in the qualifying exam. If not met, applicants must clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with a minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with an overall score of 6.\n\nMBA in International Business: Applicants must have a Bachelor\'s Degree from a recognized university and must demonstrate proficiency in English. (Source: Master of Business Administration (MBA) Program) MSc in Applied Psychology: Prospective students should have a bachelor\'s degree of a minimum of three years in any discipline with at least 50% aggregate marks from a recognized university. (Source: Master of Science in Applied Psychology) MSc in Medical Biotechnology: Eligibility criteria require students to hold a bachelor\'s degree in any Life Science subject from a recognized university with at least 50% aggregate marks in their undergraduate degree. (Source: Msc in Medical Biotechnology) MSc in Information Science: Candidates should be a graduate with a BSc(IT)/BSc(ISM)/BCA/BSc (Computer Science)/B.Sc./BBA (IT)/B. Tech/B.E from a recognized University or any other graduate with a minimum of three years of experience in the field of IT. (Source: MSc Information Systems)\n\n1.Applicants must hold a Bachelor’s Degree from a recognised university, making the program accessible to fresh graduates, working executives, and self-employed professionals. 2. Minimum 60% in English in the qualifying exam. If not met, applicants must clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with a minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with an overall score of 6.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:41',NULL);
INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2519,'01KWJDMG0KVVRE5WQ8FAZ3643K',145,'Master of Design (MDes)- Sustainable Design','bachelors',24,'English','Toolkit source: non_exclusive / UAE / row 58.','REQUIREMENTS / DOCUMENTS:\n1. Bachelor\'s degree in Architecture, Engineering, or related fields.\nCandidates must have achieved at least 50% in aggregate marks in their qualifying examination.                    2. Portfolio submission and personal interview (optional).                                                                 3. Minimum 60% in English in the qualifying exam. If not met, applicants must clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with a minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with an overall score of 6.\n\nMBA in International Business: Applicants must have a Bachelor\'s Degree from a recognized university and must demonstrate proficiency in English. (Source: Master of Business Administration (MBA) Program) MSc in Applied Psychology: Prospective students should have a bachelor\'s degree of a minimum of three years in any discipline with at least 50% aggregate marks from a recognized university. (Source: Master of Science in Applied Psychology) MSc in Medical Biotechnology: Eligibility criteria require students to hold a bachelor\'s degree in any Life Science subject from a recognized university with at least 50% aggregate marks in their undergraduate degree. (Source: Msc in Medical Biotechnology) MSc in Information Science: Candidates should be a graduate with a BSc(IT)/BSc(ISM)/BCA/BSc (Computer Science)/B.Sc./BBA (IT)/B. Tech/B.E from a recognized University or any other graduate with a minimum of three years of experience in the field of IT. (Source: MSc Information Systems)\n\n1. Bachelor’s degree in Architecture, Engineering, or related fields. Candidates must have achieved at least 50% in aggregate marks in their qualifying examination. 2. Portfolio submission and personal interview (optional). 3. Minimum 60% in English in the qualifying exam. If not met, applicants must clear the Manipal Enablers English Competency Test and/or complete a 6-week Bridge Program with a minimum 60% pass grade. If the medium of instruction was not English, submit IELTS/TOEFL with an overall score of 6.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:41',NULL);
