INSERT INTO `courses` (`id`, `public_id`, `university_id`, `name`, `degree_level`, `duration_months`, `language`, `description`, `eligibility_criteria`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (2542,'01KWJDMG0XHF64MVY8A9K75FZF',146,'Advanced Diploma in Fashion Design & Manufacture - LEVEL : 5 (ADVANCED DIPLOMA)','diploma',24,'English','Toolkit source: non_exclusive / UAE / row 83.','ELIGIBILITY:\nGeneral: For programs like the Diploma in Fashion Design and Undergraduate in Fashion Design, candidates must have passed the 12th grade from a recognized board.\n\nAlternative qualifications: Candidates with an A Level/IB Diploma or equivalent are also eligible.\n\nPortfolio review: Students who have passed the 10th grade (O Levels or equivalent) and have a Foundation in Art & Design may be considered based on a portfolio review.\n\nREQUIREMENTS / DOCUMENTS:\n12th Grade / A Level / IB Diploma or equivalent. 10th Grade / GCSE / MYP with a foundation in fashion may also be considered.\n\nGeneral: For programs like the Diploma in Fashion Design and Undergraduate in Fashion Design, candidates must have passed the 12th grade from a recognized board. Alternative qualifications: Candidates with an A Level/IB Diploma or equivalent are also eligible. Portfolio review: Students who have passed the 10th grade (O Levels or equivalent) and have a Foundation in Art & Design may be considered based on a portfolio review.\n\n12th Grade / A Level / IB Diploma or equivalent. 10th Grade / GCSE / MYP with a foundation in fashion may also be considered.','active',NULL,'2026-07-03 03:31:50','2026-07-13 23:24:41',NULL);
